import { ShopApi, StorefrontResponse, StorefrontItem, ShopPurchaseResponse, ShopPurchaseResult, ShopOrderHistoryResponse } from './ShopApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

const INTERACTIVE_PURCHASE_TIMEOUT = -1

/**
 * Host-side code for "the player closed the top-up paywall we opened because
 * they were short on currency" (H5ShopHandler). It arrives as a rejection —
 * the same channel as a genuine failure — which meant every game that didn't
 * inspect `err.code` reported a deliberate dismissal as a hard failure.
 */
const USER_CANCELLED_CODE = 'USER_CANCELLED'

function isUserCancelled(error: unknown): boolean {
  return (error as { code?: unknown } | null)?.code === USER_CANCELLED_CODE
}

interface PurchaseArgs {
  itemId: string
  idempotencyKey: string
  collectionId?: string
}

export class RpcShopApi implements ShopApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async getCatalog(includeInactive?: boolean, includeExpired?: boolean, includeUnreleased?: boolean): Promise<StorefrontResponse> {
    const response = await this.rpcClient.call<StorefrontResponse>(
      RundotGameMessageId.H5_SHOP_GET_CATALOG,
      { includeInactive, includeExpired, includeUnreleased },
    )
    return response
  }

  async getItemDetail(itemId: string): Promise<StorefrontItem> {
    const response = await this.rpcClient.call<{ configId: string; item: StorefrontItem }>(
      RundotGameMessageId.H5_SHOP_GET_ITEM_DETAIL,
      { itemId },
    )
    return response.item
  }

  async purchase(itemId: string, idempotencyKey: string): Promise<ShopPurchaseResult> {
    return this.callPurchase({ itemId, idempotencyKey })
  }

  async purchaseCollectionItem(collectionId: string, itemId: string, idempotencyKey: string): Promise<ShopPurchaseResult> {
    return this.callPurchase({ itemId, idempotencyKey, collectionId })
  }

  /**
   * Turn the host's cancel rejection into a resolved result so a dismissed
   * paywall is a RESULT, not an error. Everything else still rejects, so real
   * failures keep reaching the game's catch block.
   *
   * This lives in the SDK rather than the host on purpose: games bundle their
   * own SDK copy, so already-deployed games keep the old rejection until they
   * rebuild, and the new contract holds against every host version that
   * reports the dismissal with `USER_CANCELLED` — old and new alike.
   */
  private async callPurchase(args: PurchaseArgs): Promise<ShopPurchaseResult> {
    try {
      return await this.rpcClient.call<ShopPurchaseResponse>(
        RundotGameMessageId.H5_SHOP_PURCHASE,
        args,
        INTERACTIVE_PURCHASE_TIMEOUT,
      )
    } catch (error: unknown) {
      if (!isUserCancelled(error)) throw error
      return { success: false, cancelled: true, order: null }
    }
  }

  async getOrder(orderId: string): Promise<ShopPurchaseResponse> {
    const response = await this.rpcClient.call<ShopPurchaseResponse>(
      RundotGameMessageId.H5_SHOP_GET_ORDER_STATUS,
      { orderId },
    )
    return response
  }

  async getOrderHistory(options?: { limit?: number }): Promise<ShopOrderHistoryResponse> {
    const response = await this.rpcClient.call<ShopOrderHistoryResponse>(
      RundotGameMessageId.H5_SHOP_GET_ORDER_HISTORY,
      { limit: options?.limit },
    )
    return response
  }

  async requestRefund(orderId: string, reasonCode: string): Promise<ShopPurchaseResponse> {
    const response = await this.rpcClient.call<ShopPurchaseResponse>(
      RundotGameMessageId.H5_SHOP_REQUEST_REFUND,
      { orderId, reasonCode },
    )
    return response
  }
}
