import {
  EntitlementApi,
  Entitlement,
  LedgerEntry,
} from './EntitlementApi'
import { generateId } from '../utils/idGenerator'
import { mockLog } from '../MockDebug'
import { RundotApiError } from '../errors'

const TAG = 'Mock Entitlements'

export class MockEntitlementApi implements EntitlementApi {
  private entitlements: Entitlement[] = [
    {
      docId: 'mock-ent-1',
      userId: 'mock-user',
      gameId: 'mock-game',
      entitlementId: 'boost_speed',
      quantity: 5,
      consumable: true,
      status: 'active',
      expiresAt: null,
      createdAt: Date.now() - 86400000,
      updatedAt: Date.now() - 86400000,
      revokedAt: null,
    },
    {
      docId: 'mock-ent-2',
      userId: 'mock-user',
      gameId: 'mock-game',
      entitlementId: 'sword_legendary',
      quantity: 1,
      consumable: false,
      status: 'active',
      expiresAt: null,
      createdAt: Date.now() - 172800000,
      updatedAt: Date.now() - 172800000,
      revokedAt: null,
    },
    {
      docId: 'mock-ent-3',
      userId: 'mock-user',
      gameId: 'mock-game',
      entitlementId: 'vip_pass',
      quantity: 1,
      consumable: false,
      status: 'active',
      expiresAt: Date.now() + 604800000,
      createdAt: Date.now() - 86400000,
      updatedAt: Date.now() - 86400000,
      revokedAt: null,
    },
  ]

  private ledger: LedgerEntry[] = [
    {
      ledgerId: 'mock-ledger-1',
      userId: 'mock-user',
      gameId: 'mock-game',
      entitlementId: 'boost_speed',
      change: 5,
      action: 'grant',
      source: 'admin',
      referenceId: 'mock-ref-1',
      reason: 'Initial grant',
      createdAt: Date.now() - 86400000,
      balanceAfter: 5,
    },
    {
      ledgerId: 'mock-ledger-2',
      userId: 'mock-user',
      gameId: 'mock-game',
      entitlementId: 'sword_legendary',
      change: 1,
      action: 'grant',
      source: 'purchase',
      referenceId: 'mock-ref-2',
      reason: null,
      createdAt: Date.now() - 172800000,
      balanceAfter: 1,
    },
    {
      ledgerId: 'mock-ledger-3',
      userId: 'mock-user',
      gameId: 'mock-game',
      entitlementId: 'vip_pass',
      change: 1,
      action: 'grant',
      source: 'purchase',
      referenceId: 'mock-ref-3',
      reason: null,
      createdAt: Date.now() - 86400000,
      balanceAfter: 1,
    },
  ]

  async listEntitlements(): Promise<Entitlement[]> {
    return this.entitlements.filter((e) => e.status === 'active')
  }

  async getQuantity(entitlementId: string): Promise<number> {
    const entitlement = this.entitlements.find(
      (e) => e.entitlementId === entitlementId && e.status === 'active',
    )
    return entitlement?.quantity ?? 0
  }

  async consumeEntitlement(
    entitlementId: string,
    quantity: number,
    callback?: (entitlement: Entitlement, referenceId: string) => void | Promise<void>,
    reason?: string,
    referenceId?: string,
  ): Promise<Entitlement> {
    mockLog(TAG, `consumeEntitlement id=${entitlementId} qty=${quantity}`)
    referenceId = referenceId ?? generateId()

    if (!Number.isFinite(quantity) || quantity <= 0 || !Number.isInteger(quantity)) {
      // Matches the production surface: the game observes a RundotApiError.
      // Mirrors validatePositiveInteger in server/cloud-run/src/utils/validation.ts.
      throw new RundotApiError('UNKNOWN', 'quantity must be a positive integer', 0)
    }

    const entitlement = this.entitlements.find(
      (e) => e.entitlementId === entitlementId && e.status === 'active',
    )

    if (!entitlement) {
      throw new Error(`Entitlement not found: ${entitlementId}`)
    }
    if (!entitlement.consumable) {
      throw new Error(`Entitlement is not consumable: ${entitlementId}`)
    }
    if (entitlement.quantity < quantity) {
      throw new Error(
        `Insufficient quantity: have ${entitlement.quantity}, need ${quantity}`,
      )
    }

    entitlement.quantity -= quantity
    entitlement.updatedAt = Date.now()

    this.ledger.push({
      ledgerId: `mock-ledger-${Date.now()}`,
      userId: entitlement.userId,
      gameId: entitlement.gameId,
      entitlementId,
      change: -quantity,
      action: 'consume',
      source: 'progression',
      referenceId,
      reason: reason ?? null,
      createdAt: Date.now(),
      balanceAfter: entitlement.quantity,
    })

    const result = { ...entitlement }
    if (callback) {
      try {
        await callback(result, referenceId)
      } catch (e) {
        console.warn('[RUN:mock] consumeEntitlement callback threw, but consume succeeded', e)
      }
    }
    return result
  }

  async getLedger(entitlementId?: string, limit?: number, startAfter?: number): Promise<LedgerEntry[]> {
    let entries = [...this.ledger]

    if (entitlementId) {
      entries = entries.filter((e) => e.entitlementId === entitlementId)
    }

    entries.sort((a, b) => b.createdAt - a.createdAt)

    if (startAfter) {
      entries = entries.filter((e) => e.createdAt < startAfter)
    }

    if (limit) {
      entries = entries.slice(0, limit)
    }

    return entries
  }
}
