import type {
  CaptureConsent,
  ClipPersistOptions,
  ClipResult,
  ClipsApi,
  ClipsSupport,
  StartClipRecordingOptions,
} from './ClipsApi'
import type { UgcEntry } from '../ugc/UgcApi'

export class MockClipsApi implements ClipsApi {
  async isSupportedAsync(): Promise<ClipsSupport> {
    return { canRecord: false, canUseMicrophone: false, canUseCamera: false, reason: 'mock host' }
  }
  async getCaptureConsentAsync(): Promise<CaptureConsent> {
    return { status: 'granted', canAskAgain: true }
  }
  async requestCaptureConsentAsync(_opts?: { includesCamera?: boolean }): Promise<CaptureConsent> {
    return { status: 'granted', canAskAgain: true }
  }
  useGameAudio(_node: AudioNode): void {}
  async startRecordingAsync(_options?: StartClipRecordingOptions): Promise<void> {
    console.warn('[RUN:mock] clips.startRecordingAsync is a no-op')
  }
  captureFrame(): void {}
  async stopRecordingAsync(_persist?: ClipPersistOptions): Promise<ClipResult> {
    throw new Error('[RUN:mock] clips recording is not available in the mock host')
  }
  async cancelRecordingAsync(): Promise<void> {}
  async publishClipAsync(_ugcId: string): Promise<UgcEntry> {
    throw new Error('[RUN:mock] clips.publishClipAsync is not available in the mock host')
  }
}
