import type {
  FilesApi,
  UploadParams,
  UploadResult,
  FileEntry,
  GetUrlParams,
  GetUrlsParams,
  GetUrlsResult,
  GetMetadataParams,
  ExistsParams,
  BatchMetadataParams,
  BatchMetadataResult,
  BatchExistsParams,
  BatchExistsResult,
  ListParams,
  ListResult,
  StorageQuota,
  TransformParams,
  TransformResult,
  ArchiveExtractParams,
  ArchiveExtractResult,
  ConfirmUploadOptions,
  BatchConfirmOptions,
  FilesJobEvent,
  ExportToCloudinaryParams,
  CloudinaryExportResult,
  BatchUploadParams,
  BatchUploadResult,
  BatchConfirmResult,
  BatchCopyParams,
  BatchCopyResult,
} from './FilesApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

export class RpcFilesApi implements FilesApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async upload(params: UploadParams): Promise<UploadResult> {
    return this.rpcClient.call<UploadResult>(
      RundotGameMessageId.H5_FILES_UPLOAD,
      params,
    )
  }

  async confirmUpload(key: string, options?: ConfirmUploadOptions): Promise<FileEntry> {
    return this.rpcClient.call<FileEntry>(
      RundotGameMessageId.H5_FILES_CONFIRM_UPLOAD,
      { key, ...options },
      -1,
    )
  }

  async batchUpload(params: BatchUploadParams): Promise<BatchUploadResult> {
    return this.rpcClient.call<BatchUploadResult>(
      RundotGameMessageId.H5_FILES_BATCH_UPLOAD,
      params,
    )
  }

  async batchCopy(params: BatchCopyParams): Promise<BatchCopyResult> {
    return this.rpcClient.call<BatchCopyResult>(
      RundotGameMessageId.H5_FILES_BATCH_COPY,
      params,
      -1,
    )
  }

  async batchConfirm(keys: string[], options?: BatchConfirmOptions): Promise<BatchConfirmResult> {
    return this.rpcClient.call<BatchConfirmResult>(
      RundotGameMessageId.H5_FILES_BATCH_CONFIRM,
      { keys, ...options },
    )
  }

  async getUrl(params: GetUrlParams): Promise<string> {
    const result = await this.rpcClient.call<{ url: string }>(
      RundotGameMessageId.H5_FILES_GET_URL,
      params,
    )
    return result.url
  }

  async getUrls(params: GetUrlsParams): Promise<GetUrlsResult> {
    return this.rpcClient.call<GetUrlsResult>(
      RundotGameMessageId.H5_FILES_GET_URLS,
      params,
    )
  }

  async getMetadata(params: GetMetadataParams): Promise<FileEntry> {
    return this.rpcClient.call<FileEntry>(
      RundotGameMessageId.H5_FILES_GET_METADATA,
      params,
    )
  }

  async exists(params: ExistsParams): Promise<boolean> {
    return this.rpcClient.call<boolean>(
      RundotGameMessageId.H5_FILES_EXISTS,
      params,
    )
  }

  async batchGetMetadata(params: BatchMetadataParams): Promise<BatchMetadataResult> {
    return this.rpcClient.call<BatchMetadataResult>(
      RundotGameMessageId.H5_FILES_BATCH_METADATA,
      params,
    )
  }

  async batchExists(params: BatchExistsParams): Promise<BatchExistsResult> {
    return this.rpcClient.call<BatchExistsResult>(
      RundotGameMessageId.H5_FILES_BATCH_EXISTS,
      params,
    )
  }

  async delete(key: string): Promise<void> {
    await this.rpcClient.call(
      RundotGameMessageId.H5_FILES_DELETE,
      { key },
    )
  }

  async list(params?: ListParams): Promise<ListResult> {
    return this.rpcClient.call<ListResult>(
      RundotGameMessageId.H5_FILES_LIST,
      params ?? {},
    )
  }

  async getQuota(): Promise<StorageQuota> {
    return this.rpcClient.call<StorageQuota>(
      RundotGameMessageId.H5_FILES_GET_QUOTA,
      {},
    )
  }

  async hasStorageAvailable(sizeBytes: number, contentType?: string): Promise<boolean> {
    const quota = await this.getQuota()
    const cap = contentType === 'application/zip' ? quota.maxArchiveBytes : quota.maxFileBytes
    return quota.availableBytes >= sizeBytes && sizeBytes <= cap
  }

  async setVisibility(key: string, visibility: 'private' | 'public'): Promise<FileEntry> {
    return this.rpcClient.call<FileEntry>(
      RundotGameMessageId.H5_FILES_SET_VISIBILITY,
      { key, visibility },
    )
  }

  async transform(params: ArchiveExtractParams): Promise<ArchiveExtractResult>
  async transform(params: TransformParams): Promise<TransformResult>
  async transform(params: TransformParams): Promise<TransformResult | ArchiveExtractResult> {
    // Forwarded generically over the existing transform message id; the host
    // dispatches by `op`, so `unzip` needs no new RPC channel.
    return this.rpcClient.call<TransformResult | ArchiveExtractResult>(
      RundotGameMessageId.H5_FILES_TRANSFORM,
      params,
      -1,
    )
  }

  async exportToCloudinary(params: ExportToCloudinaryParams): Promise<CloudinaryExportResult> {
    return this.rpcClient.call<CloudinaryExportResult>(
      RundotGameMessageId.H5_FILES_EXPORT_CLOUDINARY,
      params,
      -1,
    )
  }

  async getCompletedJobs(): Promise<FilesJobEvent[]> {
    return this.rpcClient.call<FilesJobEvent[]>(
      RundotGameMessageId.H5_POLL_COMPLETED_JOBS,
      { type: 'files' },
    )
  }
}
