import {
  CanShareFileResult,
  ComposeSocialPostOptions,
  ComposeSocialPostResult,
  FollowMePlatform,
  FollowMeResult,
  QRCodeResult,
  ShareClickData,
  ShareFileOptions,
  ShareFileResult,
  ShareLinkResult,
  ShareMetadata,
  SocialApi,
  SocialQRCodeOptions,
} from './SocialApi';
import {
  validateShareParams,
  validateShareMetadata,
  validateClickMetadata,
  validateShareFile,
  validateComposePost,
  stripComposeControlChars,
} from './validateShare';
import { buildRedditComposerUrl, buildXComposerUrl } from './composeUrl';

const MOCK_QR_CODE =
  'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';

const MOCK_SHARE_LINK_ID = 'mock-share-id';

export class MockSocialApi implements SocialApi {
  async shareLinkAsync(options: {
    shareParams: Record<string, string>;
    metadata?: ShareMetadata;
    slug?: string;
  }): Promise<ShareLinkResult> {
    validateShareParams(options.shareParams);
    validateShareMetadata(options.metadata);
    const shareUrl = this.createMockUrl(options.shareParams);

    if (typeof navigator !== 'undefined' && navigator.clipboard) {
      try {
        await navigator.clipboard.writeText(shareUrl);
      } catch (error) {
        console.warn(
          '[RUN:mock] Failed to copy share URL to clipboard',
          error,
        );
      }
    }

    return { shareUrl, shareLinkId: MOCK_SHARE_LINK_ID };
  }

  async createQRCodeAsync(options: {
    shareParams: Record<string, string>;
    qrOptions?: SocialQRCodeOptions;
    metadata?: ShareMetadata;
    slug?: string;
  }): Promise<QRCodeResult> {
    validateShareParams(options.shareParams);
    validateShareMetadata(options.metadata);
    const shareUrl = this.createMockUrl(options.shareParams);

    return {
      shareUrl,
      qrCode: MOCK_QR_CODE,
      shareLinkId: MOCK_SHARE_LINK_ID,
    };
  }

  async addShareClickDataAsync(options: {
    shareLinkId: string;
    metadata: Record<string, string>;
  }): Promise<void> {
    validateClickMetadata(options.metadata);
  }

  async getShareClicksAsync(options: {
    shareLinkId: string;
  }): Promise<{ clicks: ShareClickData[]; truncated: boolean }> {
    return { clicks: [], truncated: false };
  }

  async getMyShareClickDataAsync(options: {
    shareLinkId: string;
  }): Promise<ShareClickData | null> {
    return null;
  }

  async shareFileAsync(options: ShareFileOptions): Promise<ShareFileResult> {
    validateShareFile(options);
    console.warn('[RUN:mock] shareFileAsync called — returning cancelled: false');
    return { cancelled: false };
  }

  async canShareFileAsync(): Promise<CanShareFileResult> {
    return { supported: false };
  }

  async composeSocialPostAsync(
    options: ComposeSocialPostOptions,
  ): Promise<ComposeSocialPostResult> {
    const text = stripComposeControlChars(options.text ?? '');
    const title =
      options.title === undefined
        ? undefined
        : stripComposeControlChars(options.title);
    validateComposePost({ text, title, subreddit: options.subreddit });
    if (options.media) validateShareFile(options.media);
    validateShareParams(options.shareParams);
    validateShareMetadata(options.metadata);

    const link = options.shareParams
      ? this.createMockUrl(options.shareParams)
      : undefined;

    // Share-sheet destinations need host UI (caption toast + OS share sheet);
    // the mock has neither, so it mirrors shareFileAsync's log/no-op stance.
    if (options.platform === 'tiktok' || options.platform === 'instagram') {
      console.warn(
        `[RUN:mock] composeSocialPostAsync: "${options.platform}" is a share-sheet destination with no mock UI — returning completed: false`,
      );
      return { completed: false };
    }

    const destination = options.platform ?? 'x';
    const url =
      destination === 'reddit'
        ? buildRedditComposerUrl({ text, link, title, subreddit: options.subreddit })
        : buildXComposerUrl(text, link);

    // Playground runs in-page (no sandboxed iframe), so opening the composer
    // directly works here.
    if (typeof window !== 'undefined' && typeof window.open === 'function') {
      window.open(url, '_blank', 'noopener,noreferrer');
    } else {
      console.warn(`[RUN:mock] composeSocialPostAsync composer URL: ${url}`);
    }

    return { completed: true, destination };
  }

  async openXFollowMeLinkAsync(): Promise<FollowMeResult> {
    console.warn('[RUN:mock] openXFollowMeLinkAsync called — returning not_configured');
    return { completed: false, reason: 'not_configured' };
  }

  async openInstagramFollowMeLinkAsync(): Promise<FollowMeResult> {
    console.warn('[RUN:mock] openInstagramFollowMeLinkAsync called — returning not_configured');
    return { completed: false, reason: 'not_configured' };
  }

  async openTikTokFollowMeLinkAsync(): Promise<FollowMeResult> {
    console.warn('[RUN:mock] openTikTokFollowMeLinkAsync called — returning not_configured');
    return { completed: false, reason: 'not_configured' };
  }

  async openDiscordFollowMeLinkAsync(): Promise<FollowMeResult> {
    console.warn('[RUN:mock] openDiscordFollowMeLinkAsync called — returning not_configured');
    return { completed: false, reason: 'not_configured' };
  }

  async getConfiguredFollowMePlatformsAsync(): Promise<FollowMePlatform[]> {
    return [];
  }

  private createMockUrl(_shareParams: Record<string, string>): string {
    console.warn('[RUN:mock] Share params are stored online — mock URL is just a template')
    console.warn('[RUN:mock] Actual share URL looks like: https://mock-share-url.com/97dt/mock-share-id')
    return `https://mock-share-url.com/97dt/mock-share-id`;
  }
}
