import { LiveOpsApi, LiveOpsConfigResult, LiveOpsRawConfig } from './LiveOpsApi'
import { ExposureDeduper, LiveOpsHooks } from './LiveOpsCache'
import { LiveOpsSection, resolveLiveOpsSection } from './resolveLiveOps'

/**
 * Mock LiveOps — serves the local `rundot/liveops.config.json` `client` section so
 * you can develop against LiveOps without playground sign-in or a backend. The
 * section comes from either an explicit `configure()` (tests) or a live provider
 * MockHost wires to `rundotGameApi._mock.liveops.client` (the Vite plugin injects
 * that from the on-disk file; edits hot-reload). Read live on every call — the
 * same pure resolver as prod, anchored to `Date.now()`, so scheduled overrides
 * flip on schedule.
 */
export class MockLiveOpsApi implements LiveOpsApi {
  private explicitClient: LiveOpsSection | undefined
  private configured = false
  private deduper: ExposureDeduper

  constructor(
    private getClient?: () => LiveOpsSection | undefined,
    private hooks?: LiveOpsHooks,
  ) {
    this.deduper = new ExposureDeduper(hooks?.onExposure)
  }

  /** Explicit override (wins over the provider). Used by tests and programmatic setup. */
  configure(config: { client?: LiveOpsSection }): void {
    this.explicitClient = config.client
    this.configured = true
  }

  clearConfigCache(): void {
    /* no-op: mock resolves live from in-memory rules */
  }

  private resolveClient(): LiveOpsSection | undefined {
    if (this.configured) return this.explicitClient
    return this.getClient?.()
  }

  async getConfigAsync(): Promise<LiveOpsConfigResult> {
    const unitId = this.hooks?.getUnitId?.()
    const resolved = resolveLiveOpsSection(this.resolveClient(), Date.now(), unitId)
    if (unitId !== undefined) this.deduper.record(unitId, resolved.assignments, 'mock')
    return { ...resolved, configVersion: 'mock' }
  }

  async getRawConfigAsync(): Promise<LiveOpsRawConfig> {
    const client = this.resolveClient()
    return {
      values: client?.values ?? {},
      overrides: client?.overrides ?? [],
      experiments: client?.experiments ?? [],
      configVersion: 'mock',
      serverTimeMs: Date.now(),
    }
  }
}
