import { ImageGenApi, ImageGenParams, ImageGenResult, ImageGenJobEvent, DepthEstimationParams, DepthEstimationResult, RemoveBackgroundParams, RemoveBackgroundResult, UpscaleImageParams, UpscaleImageResult } from './ImageGenApi';
import { assertValidImageGenSeed } from './validateSeed';
import { RpcClient } from '../rpc';
import { RundotGameMessageId } from '../RundotGameMessageId';
import { mapCreditsExhaustion } from '../credits/CreditsApi';

export class RpcImageGenApi implements ImageGenApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async generate(params: ImageGenParams): Promise<ImageGenResult> {
    assertValidImageGenSeed(params.seed);
    // Surface player creator-credit exhaustion as a typed CreditsExhaustedError.
    return mapCreditsExhaustion(
      this.rpcClient.call<ImageGenResult>(
        RundotGameMessageId.H5_IMAGE_GEN_GENERATE,
        params,
        -1,
      ),
    );
  }

  async estimateDepth(params: DepthEstimationParams): Promise<DepthEstimationResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<DepthEstimationResult>(
        RundotGameMessageId.H5_IMAGE_GEN_ESTIMATE_DEPTH,
        params,
        -1,
      ),
    );
  }

  async removeBackground(params: RemoveBackgroundParams): Promise<RemoveBackgroundResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<RemoveBackgroundResult>(
        RundotGameMessageId.H5_IMAGE_GEN_REMOVE_BACKGROUND,
        params,
        -1,
      ),
    );
  }

  async upscaleImage(params: UpscaleImageParams): Promise<UpscaleImageResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<UpscaleImageResult>(
        RundotGameMessageId.H5_IMAGE_GEN_UPSCALE_IMAGE,
        params,
        -1,
      ),
    );
  }

  async getCompletedJobs(): Promise<ImageGenJobEvent[]> {
    return this.rpcClient.call<ImageGenJobEvent[]>(
      RundotGameMessageId.H5_POLL_COMPLETED_JOBS,
      { type: 'imageGen' },
    );
  }
}
