import { RpcClient } from '../rpc';
import { RundotGameMessageId } from '../RundotGameMessageId';
import {
  CanShareFileResult,
  ComposeSocialPostOptions,
  ComposeSocialPostResult,
  FollowMePlatform,
  FollowMeResult,
  QRCodeResult,
  ShareClickData,
  ShareFileOptions,
  ShareFileResult,
  ShareLinkResult,
  ShareMetadata,
  SHARE_FILE_ALLOWED_MIME_TYPES,
  SHARE_FILE_MAX_SIZE_BYTES,
  SocialApi,
  SocialQRCodeOptions,
} from './SocialApi';
import {
  stripComposeControlChars,
  validateComposePost,
  validateShareFile,
} from './validateShare';

export class RpcSocialApi implements SocialApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async shareLinkAsync(options: {
    shareParams: Record<string, string>;
    metadata?: ShareMetadata;
    slug?: string;
  }): Promise<ShareLinkResult> {
    const result = (await this.rpcClient.call(RundotGameMessageId.SHARE_LINK, {
      shareParams: options.shareParams,
      metadata: options.metadata ?? {},
      slug: options.slug,
    })) as { shareUrl: string; shareLinkId: string };

    return {
      shareUrl: result.shareUrl,
      shareLinkId: result.shareLinkId,
    };
  }

  async createQRCodeAsync(options: {
    shareParams: Record<string, string>;
    metadata?: ShareMetadata;
    qrOptions?: SocialQRCodeOptions;
    slug?: string;
  }): Promise<QRCodeResult> {
    const result = (await this.rpcClient.call(
      RundotGameMessageId.CREATE_SHARE_QRCODE,
      {
        shareParams: options.shareParams,
        metadata: options.metadata ?? {},
        qrOptions: options.qrOptions ?? {},
        slug: options.slug,
      },
    )) as { shareUrl: string; qrCode: string; shareLinkId: string };

    return {
      shareUrl: result.shareUrl,
      qrCode: result.qrCode,
      shareLinkId: result.shareLinkId,
    };
  }

  async addShareClickDataAsync(options: {
    shareLinkId: string;
    metadata: Record<string, string>;
  }): Promise<void> {
    await this.rpcClient.call(RundotGameMessageId.SHARE_ADD_CLICK_DATA, {
      shareLinkId: options.shareLinkId,
      metadata: options.metadata,
    });
  }

  async getShareClicksAsync(options: {
    shareLinkId: string;
  }): Promise<{ clicks: ShareClickData[]; truncated: boolean }> {
    const result = (await this.rpcClient.call(
      RundotGameMessageId.SHARE_GET_CLICKS,
      { shareLinkId: options.shareLinkId },
    )) as { clicks: ShareClickData[]; truncated: boolean };

    return result;
  }

  async getMyShareClickDataAsync(options: {
    shareLinkId: string;
  }): Promise<ShareClickData | null> {
    const result = (await this.rpcClient.call(
      RundotGameMessageId.SHARE_GET_MY_CLICK_DATA,
      { shareLinkId: options.shareLinkId },
    )) as ShareClickData | null;

    return result;
  }

  async shareFileAsync(options: ShareFileOptions): Promise<ShareFileResult> {
    const { data, filename, mimeType, title, text } = options;

    if (!(SHARE_FILE_ALLOWED_MIME_TYPES as readonly string[]).includes(mimeType)) {
      throw new Error(
        `unsupported MIME type "${mimeType}". Allowed: ${SHARE_FILE_ALLOWED_MIME_TYPES.join(', ')}`,
      );
    }

    // Reject oversized Blob/ArrayBuffer before costly base64 encoding
    const rawSize =
      data instanceof Blob ? data.size
      : data instanceof ArrayBuffer ? data.byteLength
      : undefined;
    if (rawSize !== undefined && rawSize > SHARE_FILE_MAX_SIZE_BYTES) {
      throw new Error(
        `file size (${rawSize} bytes) exceeds max allowed (${SHARE_FILE_MAX_SIZE_BYTES} bytes)`,
      );
    }

    const base64 = await this.toBase64(data);

    // For pre-encoded string inputs, verify size from the base64 length
    if (rawSize === undefined) {
      const len = base64.length;
      const paddingChars = (base64[len - 1] === '=' ? 1 : 0) + (base64[len - 2] === '=' ? 1 : 0);
      const sizeBytes = Math.floor((len * 3) / 4) - paddingChars;
      if (sizeBytes > SHARE_FILE_MAX_SIZE_BYTES) {
        throw new Error(
          `file size (${sizeBytes} bytes) exceeds max allowed (${SHARE_FILE_MAX_SIZE_BYTES} bytes)`,
        );
      }
    }

    const result = (await this.rpcClient.call(
      RundotGameMessageId.SHARE_FILE,
      { base64, filename, mimeType, title, text },
    )) as { cancelled: boolean };

    return { cancelled: result.cancelled };
  }

  async canShareFileAsync(): Promise<CanShareFileResult> {
    const result = (await this.rpcClient.call(
      RundotGameMessageId.CAN_SHARE_FILE,
      {},
    )) as { supported: boolean };

    return { supported: result.supported };
  }

  async composeSocialPostAsync(
    options: ComposeSocialPostOptions,
  ): Promise<ComposeSocialPostResult> {
    const text = stripComposeControlChars(options.text ?? '');
    const title =
      options.title === undefined
        ? undefined
        : stripComposeControlChars(options.title);
    validateComposePost({ text, title, subreddit: options.subreddit });

    let media:
      | { base64: string; filename: string; mimeType: string }
      | undefined;
    if (options.media) {
      validateShareFile(options.media);
      media = {
        base64: await this.toBase64(options.media.data),
        filename: options.media.filename,
        mimeType: options.media.mimeType,
      };
    }

    // No timeout (-1): this call blocks on a human decision in the
    // host-rendered destination sheet. The host guarantees resolution on
    // completion, dismiss, or preemption, so the promise cannot leak.
    const result = (await this.rpcClient.call(
      RundotGameMessageId.SHARE_COMPOSE_POST,
      {
        text,
        title,
        subreddit: options.subreddit,
        platform: options.platform,
        shareParams: options.shareParams,
        metadata: options.metadata ?? {},
        media,
      },
      -1,
    )) as { completed: boolean; destination?: string };

    return { completed: result.completed, destination: result.destination };
  }

  async openXFollowMeLinkAsync(): Promise<FollowMeResult> {
    return this.openFollowMeLink('x');
  }

  async openInstagramFollowMeLinkAsync(): Promise<FollowMeResult> {
    return this.openFollowMeLink('instagram');
  }

  async openTikTokFollowMeLinkAsync(): Promise<FollowMeResult> {
    return this.openFollowMeLink('tiktok');
  }

  async openDiscordFollowMeLinkAsync(): Promise<FollowMeResult> {
    return this.openFollowMeLink('discord');
  }

  async getConfiguredFollowMePlatformsAsync(): Promise<FollowMePlatform[]> {
    const result = (await this.rpcClient.call(
      RundotGameMessageId.SHARE_GET_FOLLOW_ME_PLATFORMS,
      {},
    )) as { platforms: FollowMePlatform[] };

    return result.platforms;
  }

  private async openFollowMeLink(
    platform: FollowMePlatform,
  ): Promise<FollowMeResult> {
    // No timeout (-1): blocks on a human decision in the host sheet.
    const result = (await this.rpcClient.call(
      RundotGameMessageId.SHARE_OPEN_FOLLOW_ME,
      { platform },
      -1,
    )) as FollowMeResult;

    return { completed: result.completed, reason: result.reason };
  }

  private async toBase64(data: Blob | ArrayBuffer | string): Promise<string> {
    if (typeof data === 'string') {
      return data;
    }

    const blob = data instanceof Blob ? data : new Blob([data]);

    return new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (): void => {
        const dataUrl = reader.result as string;
        const commaIdx = dataUrl.indexOf(',');
        resolve(commaIdx >= 0 ? dataUrl.slice(commaIdx + 1) : dataUrl);
      };
      reader.onerror = (): void => reject(reader.error);
      reader.readAsDataURL(blob);
    });
  }
}
