﻿import {
  AiApi,
  AiChatCompletionData,
  AiChatCompletionRequest,
  AiChatCompletionStreamChunk,
  AiChatCompletionStreamOptions,
  PromptCompletionRequest,
  toPromptWireRequest,
} from './AiApi'
import { RpcClient, Subscription } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { asCreditsExhaustedError, mapCreditsExhaustion } from '../credits/CreditsApi'

interface StreamStartResponse {
  streamId: string
}

/**
 * What actually rides the wire in `{ request: ... }`: either an open-mode
 * chat request (sans the deprecated `apiKey`) or a templated prompt-only
 * request. Both travel over the same AI_CHAT_COMPLETION* message ids; the
 * server's route-body mapping tells them apart by shape.
 */
type WireCompletionRequest =
  | Omit<AiChatCompletionRequest, 'apiKey'>
  | PromptCompletionRequest

interface StreamChunkPayload {
  streamId: string
  chunk: Extract<AiChatCompletionStreamChunk, { type: 'delta' } | { type: 'reasoning' } | { type: 'tool_call_chunk' }>
}

interface StreamDonePayload {
  streamId: string
  chunk: Extract<AiChatCompletionStreamChunk, { type: 'done' }>
}

interface StreamErrorPayload {
  streamId: string
  error: string
  message?: string
  // Canonical credits markers, present only when the host classified the failure
  // as player creator-credit exhaustion. Let the SDK rebuild the typed error.
  code?: string
  detail?: string
}

export class RpcAiApi implements AiApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async requestChatCompletionAsync(
    request: AiChatCompletionRequest,
  ): Promise<AiChatCompletionData> {
    const { apiKey: _apiKey, ...requestWithoutApiKey } = request
    // Surface player creator-credit exhaustion as a typed CreditsExhaustedError.
    return mapCreditsExhaustion(
      this.rpcClient.call<AiChatCompletionData>(
        RundotGameMessageId.AI_CHAT_COMPLETION,
        { request: requestWithoutApiKey },
        -1,
      ),
    )
  }

  async requestPromptCompletionAsync(
    request: PromptCompletionRequest,
  ): Promise<AiChatCompletionData> {
    return mapCreditsExhaustion(
      this.rpcClient.call<AiChatCompletionData>(
        RundotGameMessageId.AI_CHAT_COMPLETION,
        { request: toPromptWireRequest(request) },
        -1,
      ),
    )
  }

  async getAvailableCompletionModels(): Promise<Array<string>> {
    const response = await this.rpcClient.call<Array<string>>(
      RundotGameMessageId.AI_GET_AVAILABLE_MODELS,
      {},
      -1
    )
    return response
  }

  requestChatCompletionStreamAsync(
    request: AiChatCompletionRequest,
    options?: AiChatCompletionStreamOptions,
  ): AsyncIterable<AiChatCompletionStreamChunk> {
    const { apiKey: _apiKey, ...requestWithoutApiKey } = request
    return this.openStream(requestWithoutApiKey, options)
  }

  requestPromptCompletionStreamAsync(
    request: PromptCompletionRequest,
    options?: AiChatCompletionStreamOptions,
  ): AsyncIterable<AiChatCompletionStreamChunk> {
    return this.openStream(toPromptWireRequest(request), options)
  }

  /**
   * Shared stream machinery for both open-mode and templated streams: START
   * round-trip, CHUNK/DONE/ERROR notification fan-in, ABORT on cancel, and
   * credits-exhaustion re-typing. The wire request is the only thing that
   * differs between the two public methods.
   */
  private openStream(
    wireRequest: WireCompletionRequest,
    options?: AiChatCompletionStreamOptions,
  ): AsyncIterable<AiChatCompletionStreamChunk> {
    const rpc = this.rpcClient
    return {
      [Symbol.asyncIterator]: (): AsyncIterator<AiChatCompletionStreamChunk> => {
        // Single-FIFO buffer fed by notification handlers, drained by `next()`.
        // The two halves communicate via a pending-promise pair when next()
        // outruns producers (and vice versa).
        type QueueItem =
          | { kind: 'chunk'; value: AiChatCompletionStreamChunk }
          | { kind: 'error'; error: Error }
          | { kind: 'end' }
        const queue: QueueItem[] = []
        const waiters: Array<(item: QueueItem) => void> = []
        let streamId: string | undefined
        let ended = false
        let started = false
        let startPromise: Promise<void> | null = null
        // Set by abort/return() callers when the upstream stream hasn't been
        // assigned a streamId yet — START is still mid-flight. The START
        // resolver flushes this once it knows the id so the host doesn't
        // keep the upstream SSE socket open forever.
        let abortPending = false

        const subscriptions: Subscription[] = []
        let onAbort: (() => void) | null = null

        const sendAbortIfReady = (): void => {
          if (streamId) {
            rpc.notify(RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_ABORT, { streamId })
          } else {
            abortPending = true
          }
        }

        const push = (item: QueueItem): void => {
          if (ended && item.kind !== 'end') return
          if (item.kind !== 'chunk') ended = true
          const waiter = waiters.shift()
          if (waiter) {
            waiter(item)
          } else {
            queue.push(item)
          }
        }

        const pull = (): Promise<QueueItem> => {
          const ready = queue.shift()
          if (ready) return Promise.resolve(ready)
          return new Promise<QueueItem>((resolve) => waiters.push(resolve))
        }

        const cleanup = (): void => {
          for (const sub of subscriptions) {
            sub.unsubscribe()
          }
          subscriptions.length = 0
          if (onAbort && options?.signal) {
            options.signal.removeEventListener('abort', onAbort)
          }
          onAbort = null
        }

        // Notifications that arrived before START resolved. We have to
        // subscribe before sending START (otherwise a notification arriving
        // in the same task as the START response would land before any
        // listener), but we can't filter by streamId yet since our streamId
        // is undefined until the response. Buffering preserves both
        // invariants: nothing is dropped pre-START, and the post-START
        // drain still applies the streamId guard so other concurrent
        // streams' notifications stay out of our queue.
        type PendingNotification =
          | { kind: 'chunk'; payload: StreamChunkPayload }
          | { kind: 'done'; payload: StreamDonePayload }
          | { kind: 'error'; payload: StreamErrorPayload }
        const pendingPreStart: PendingNotification[] = []

        const handleDoneNotification = (payload: StreamDonePayload): void => {
          push({ kind: 'chunk', value: payload.chunk })
          push({ kind: 'end' })
          cleanup()
        }
        const handleErrorNotification = (payload: StreamErrorPayload): void => {
          const message =
            payload.message ?? payload.error ?? 'AI chat completion stream failed'
          // Rebuild a typed CreditsExhaustedError when the host flagged the
          // failure as player creator-credit exhaustion (code/detail present), so
          // streaming honors the same contract as the non-streaming path —
          // isCreditsExhaustedError / instanceof / billedTo all work. Any other
          // failure stays a plain Error.
          const error =
            asCreditsExhaustedError(
              Object.assign(new Error(message), {
                code: payload.code,
                detail: payload.detail,
              }),
            ) ?? new Error(message)
          push({ kind: 'error', error })
          cleanup()
        }

        const ensureStarted = async (): Promise<void> => {
          if (started) return startPromise!
          started = true
          startPromise = (async () => {
            const chunkSub = rpc.onNotification<StreamChunkPayload>(
              RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_CHUNK,
              (payload) => {
                if (streamId === undefined) {
                  pendingPreStart.push({ kind: 'chunk', payload })
                  return
                }
                if (payload.streamId !== streamId) return
                push({ kind: 'chunk', value: payload.chunk })
              },
            )
            const doneSub = rpc.onNotification<StreamDonePayload>(
              RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_DONE,
              (payload) => {
                if (streamId === undefined) {
                  pendingPreStart.push({ kind: 'done', payload })
                  return
                }
                if (payload.streamId !== streamId) return
                handleDoneNotification(payload)
              },
            )
            const errSub = rpc.onNotification<StreamErrorPayload>(
              RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_ERROR,
              (payload) => {
                if (streamId === undefined) {
                  pendingPreStart.push({ kind: 'error', payload })
                  return
                }
                if (payload.streamId !== streamId) return
                handleErrorNotification(payload)
              },
            )
            subscriptions.push(chunkSub, doneSub, errSub)

            if (options?.signal) {
              if (options.signal.aborted) {
                push({ kind: 'error', error: new Error('aborted') })
                cleanup()
                return
              }
              onAbort = (): void => {
                sendAbortIfReady()
                push({ kind: 'error', error: new Error('aborted') })
                cleanup()
              }
              options.signal.addEventListener('abort', onAbort)
            }

            try {
              const response = await rpc.call<StreamStartResponse>(
                RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_START,
                { request: wireRequest },
                -1,
              )
              streamId = response.streamId
              if (abortPending) {
                rpc.notify(RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_ABORT, { streamId })
                // Consumer already aborted — onAbort fired pre-START with the
                // error+cleanup, so any buffered notifications are stale and
                // must be discarded rather than replayed into a dead queue.
                pendingPreStart.length = 0
                return
              }
              for (const buffered of pendingPreStart) {
                if (buffered.payload.streamId !== streamId) continue
                if (buffered.kind === 'chunk') {
                  push({ kind: 'chunk', value: buffered.payload.chunk })
                } else if (buffered.kind === 'done') {
                  handleDoneNotification(buffered.payload)
                  break
                } else {
                  handleErrorNotification(buffered.payload)
                  break
                }
              }
              pendingPreStart.length = 0
            } catch (err) {
              push({
                kind: 'error',
                error: err instanceof Error ? err : new Error(String(err)),
              })
              cleanup()
            }
          })()
          return startPromise
        }

        return {
          next: async (): Promise<IteratorResult<AiChatCompletionStreamChunk>> => {
            await ensureStarted()
            const item = await pull()
            if (item.kind === 'chunk') {
              return { value: item.value, done: false }
            }
            if (item.kind === 'error') {
              throw item.error
            }
            return { value: undefined, done: true }
          },
          return: async (): Promise<IteratorResult<AiChatCompletionStreamChunk>> => {
            if (!ended) {
              sendAbortIfReady()
              // Wake any in-flight pull() with a terminal so an external
              // return() call (timeout, race, etc.) doesn't leave the
              // caller's next() promise hanging forever. push() flips
              // `ended` itself, so the assignment afterwards is just
              // belt-and-braces for early exits that don't push.
              push({ kind: 'end' })
            }
            ended = true
            cleanup()
            return { value: undefined, done: true }
          },
        }
      },
    }
  }
}
