// packages/sdk/src/credits/RpcCreditsApi.ts
import {
  CreditsApi,
  CreditBalance,
  CreditPlansCatalog,
  CreditSubscription,
  CreditsBillingContext,
  CreditsPurchaseResult,
  OpenPaywallOptions,
  Unsubscribe,
  GenerationCostEstimate,
  GenerationCostEstimateRequest,
} from './CreditsApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

/** Wire payload for {@link RundotGameMessageId.H5_CREDITS_SET_CONFIG}. */
interface CreditsConfigPatch {
  autoPaywallOnExhaustion?: boolean
  autoRetryOnPurchase?: boolean
}

export class RpcCreditsApi implements CreditsApi {
  private readonly rpcClient: RpcClient
  // Local mirrors of the host-side per-instance config. Getters read these
  // synchronously; setters mutate them and push the change to the host
  // fire-and-forget. Defaults match the host defaults (both ON).
  private autoPaywallOnExhaustion = true
  private autoRetryOnPurchase = true

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async getBillingContext(): Promise<CreditsBillingContext> {
    return this.rpcClient.call<CreditsBillingContext>(
      RundotGameMessageId.H5_CREDITS_GET_CONTEXT,
    )
  }

  async getBalance(): Promise<CreditBalance> {
    return this.rpcClient.call<CreditBalance>(
      RundotGameMessageId.H5_CREDITS_GET_BALANCE,
    )
  }

  async getSubscription(): Promise<CreditSubscription> {
    return this.rpcClient.call<CreditSubscription>(
      RundotGameMessageId.H5_CREDITS_GET_SUBSCRIPTION,
    )
  }

  async getPlans(): Promise<CreditPlansCatalog> {
    const catalog = await this.rpcClient.call<CreditPlansCatalog>(
      RundotGameMessageId.H5_CREDITS_GET_PLANS,
    )
    // Hosts older than the `plansUnavailable` marker omit it (they reject the
    // whole call on a catalog outage instead) — normalize so the field is
    // always a real boolean.
    return { ...catalog, plansUnavailable: catalog.plansUnavailable === true }
  }

  async estimateGenerationCost(request: GenerationCostEstimateRequest): Promise<GenerationCostEstimate> {
    return this.rpcClient.callT<GenerationCostEstimateRequest, GenerationCostEstimate>(
      RundotGameMessageId.H5_CREDITS_ESTIMATE_GENERATION_COST,
      request,
    )
  }

  async openPaywall(options?: OpenPaywallOptions): Promise<CreditsPurchaseResult> {
    // No timeout — the player may spend an arbitrary amount of time in the paywall.
    return this.rpcClient.callT<OpenPaywallOptions, CreditsPurchaseResult>(
      RundotGameMessageId.H5_CREDITS_OPEN_PAYWALL,
      options ?? {},
      -1,
    )
  }

  setAutoPaywallOnExhaustion(enabled: boolean): void {
    this.autoPaywallOnExhaustion = enabled
    this.pushConfig({ autoPaywallOnExhaustion: enabled })
  }

  getAutoPaywallOnExhaustion(): boolean {
    return this.autoPaywallOnExhaustion
  }

  setAutoRetryOnPurchase(enabled: boolean): void {
    this.autoRetryOnPurchase = enabled
    this.pushConfig({ autoRetryOnPurchase: enabled })
  }

  getAutoRetryOnPurchase(): boolean {
    return this.autoRetryOnPurchase
  }

  onBalanceChanged(listener: (balance: CreditBalance) => void): Unsubscribe {
    const subscription = this.rpcClient.onNotification<CreditBalance>(
      RundotGameMessageId.CREDITS_BALANCE_UPDATE,
      listener,
    )
    return () => subscription.unsubscribe()
  }

  private pushConfig(patch: CreditsConfigPatch): void {
    // Fire-and-forget. postMessage order-preservation guarantees this lands
    // before any subsequent generation call's 402, so the host reads the
    // up-to-date flags when it handles exhaustion.
    this.rpcClient.notify(RundotGameMessageId.H5_CREDITS_SET_CONFIG, patch)
  }
}
