import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import type {
  AdminImageGenApi,
  AdminSpriteGenApi,
  AdminThreeDGenApi,
  ImageGenEntry,
  ImageGenReport,
  SpriteGenEntry,
  SpriteGenReport,
  ThreeDGenEntry,
  ThreeDGenReport,
} from './AppApi'
import {
  createRpcAdminGenApi,
  createMockAdminGenApi,
  type AdminGenBrowseParams,
  type AdminGenBrowseResponse,
  type AdminGenListReportsParams,
  type AdminGenListReportsResponse,
  type AdminGenResolveAction,
} from './adminGen'

export class RpcAdminImageGenApi implements AdminImageGenApi {
  private readonly delegate: AdminImageGenApi
  constructor(rpcClient: RpcClient) {
    this.delegate = createRpcAdminGenApi<ImageGenEntry, ImageGenReport>(rpcClient, {
      browse: RundotGameMessageId.H5_APP_ADMIN_IMAGEGEN_BROWSE,
      removeEntry: RundotGameMessageId.H5_APP_ADMIN_IMAGEGEN_REMOVE_ENTRY,
      listReports: RundotGameMessageId.H5_APP_ADMIN_IMAGEGEN_LIST_REPORTS,
      resolveReport: RundotGameMessageId.H5_APP_ADMIN_IMAGEGEN_RESOLVE_REPORT,
    })
  }
  browse(params?: AdminGenBrowseParams): Promise<AdminGenBrowseResponse<ImageGenEntry>> { return this.delegate.browse(params) }
  removeEntry(generationId: string): Promise<void> { return this.delegate.removeEntry(generationId) }
  listReports(params?: AdminGenListReportsParams): Promise<AdminGenListReportsResponse<ImageGenReport>> { return this.delegate.listReports(params) }
  resolveReport(reportId: string, action: AdminGenResolveAction): Promise<void> { return this.delegate.resolveReport(reportId, action) }
}

