export interface StorefrontItem {
  itemId: string
  name: string
  description: string
  assets: {
    thumbnail?: string
    banner?: string
    icon?: string
  }
  price: { type: string; value: string }
  category: string
  unique: boolean
  active: boolean
  regions: string[]
  tags: string[]
  sortOrder: number
  releasedAt: number | null
  expiresAt: number | null
  entitlements: {
    entitlementId: string
    quantity: number
    consumable: boolean
    durationDays?: number
  }[]
  refundEligible: boolean
  refundWindowHours: number
  resolvedPrice: {
    originalPrice: { type: string; value: string }
    finalPrice: { type: string; value: string }
    appliedSales: {
      saleId: string
      discountType: string
      discountValue: number
      discountPrice?: { type: string; value: string }
    }[]
  }
}

export interface StorefrontCollectionItem {
  itemId: string
  resolvedPrice: {
    originalPrice: { type: string; value: string }
    finalPrice: { type: string; value: string }
    appliedSales: {
      saleId: string
      discountType: string
      discountValue: number
      discountPrice?: { type: string; value: string }
    }[]
  }
}

export interface StorefrontCollection {
  collectionId: string
  price: { type: string; value: string }
  entitlement: {
    consumable: boolean
    durationDays?: number
  }
  refundEligible: boolean
  refundWindowHours: number
  resolvedDefaults: {
    originalPrice: { type: string; value: string }
    finalPrice: { type: string; value: string }
    appliedSales: {
      saleId: string
      discountType: string
      discountValue: number
      discountPrice?: { type: string; value: string }
    }[]
  }
  items: StorefrontCollectionItem[]
}

export interface StorefrontResponse {
  configId: string
  items: StorefrontItem[]
  collections?: StorefrontCollection[]
}

export interface ShopOrder {
  orderId: string
  userId: string
  gameId: string
  configId: string
  collectionId?: string | null
  itemId: string
  itemSnapshot: {
    name: string
    price: { type: string; value: string }
    entitlements: { entitlementId: string; quantity: number; consumable: boolean; durationDays?: number }[]
  }
  originalPrice: { type: string; value: string }
  finalPrice: { type: string; value: string }
  appliedSales: {
    saleId: string
    discountType: string
    discountValue: number
    discountPrice?: { type: string; value: string }
  }[]
  status: string
  statusHistory: { status: string; timestamp: string; reason?: string }[]
  refund: null | {
    amount: { type: string; value: string }
    reasonCode: string
    requestedAt: string
    processedAt: string
  }
  idempotencyKey: string
  createdAt: string
  updatedAt: string
}

/** A completed purchase, or an order read back by id. The order always exists. */
export interface ShopPurchaseResponse {
  success: true
  /**
   * Never set on a completed purchase. Present only as the discriminant
   * against {@link ShopPurchaseCancelledResponse}, so `if (result.cancelled)`
   * narrows correctly in both directions.
   */
  cancelled?: false
  order: ShopOrder
}

/**
 * The player dismissed the host's top-up paywall after `purchase()` found them
 * short on currency. Nothing was charged and no order was created — this is a
 * deliberate player action, not a failure, so treat it the way you'd treat a
 * closed dialog: no error copy, no retry prompt.
 */
export interface ShopPurchaseCancelledResponse {
  success: false
  cancelled: true
  order: null
}

/**
 * What `purchase()` / `purchaseCollectionItem()` resolve to. A dismissed
 * top-up resolves as {@link ShopPurchaseCancelledResponse} rather than
 * rejecting, so a game with a plain `try/catch` no longer reports the player
 * closing the paywall as a hard failure. Genuine failures (stale catalog,
 * still-insufficient funds after a completed top-up, network) still reject.
 */
export type ShopPurchaseResult =
  | ShopPurchaseResponse
  | ShopPurchaseCancelledResponse

export interface ShopOrderHistoryResponse {
  success: boolean
  orders: ShopOrder[]
}

/**
 * Resolve pricing for a collection item from the storefront response.
 * Returns the item's resolvedPrice if it has an override, otherwise the collection's resolvedDefaults.
 * Returns null if the collection is not found.
 *
 * This is a pure function co-located with the storefront types it operates on.
 * Import it directly rather than calling it through a ShopApi instance.
 */
export function resolveCollectionItemPrice(storefront: StorefrontResponse, collectionId: string, itemId: string): StorefrontCollection['resolvedDefaults'] | null {
  const collection = storefront.collections?.find(c => c.collectionId === collectionId)
  if (!collection) return null

  const overrideItem = collection.items.find(i => i.itemId === itemId)
  return overrideItem ? overrideItem.resolvedPrice : collection.resolvedDefaults
}

export interface ShopApi {
  /** Get the full storefront catalog for the current game */
  getCatalog(includeInactive?: boolean, includeExpired?: boolean, includeUnreleased?: boolean): Promise<StorefrontResponse>

  /** Get detail for a single shop item */
  getItemDetail(itemId: string): Promise<StorefrontItem>

  /**
   * Purchase a shop item. Resolves with `{ success: false, cancelled: true }`
   * when the player dismisses the host's top-up paywall — check `success`
   * before granting anything.
   */
  purchase(itemId: string, idempotencyKey: string): Promise<ShopPurchaseResult>

  /** Purchase a collection item. Same cancel semantics as {@link ShopApi.purchase}. */
  purchaseCollectionItem(collectionId: string, itemId: string, idempotencyKey: string): Promise<ShopPurchaseResult>

  /** Get a specific order by ID */
  getOrder(orderId: string): Promise<ShopPurchaseResponse>

  /** Get order history for the current game */
  getOrderHistory(options?: { limit?: number }): Promise<ShopOrderHistoryResponse>

  /** Request a refund for an order */
  requestRefund(orderId: string, reasonCode: string): Promise<ShopPurchaseResponse>
}
