import {
  AudioGenApi,
  AudioGenParams,
  AudioGenResult,
  AudioGenJobEvent,
  ListVoicesResult,
  DesignVoicesParams,
  DesignVoicesResult,
  SaveDesignedVoiceParams,
  SaveDesignedVoiceResult,
} from './AudioGenApi';
import { RpcClient } from '../rpc';
import { RundotGameMessageId } from '../RundotGameMessageId';
import { mapCreditsExhaustion } from '../credits/CreditsApi';

export class RpcAudioGenApi implements AudioGenApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async generate(params: AudioGenParams): Promise<AudioGenResult> {
    // Surface player creator-credit exhaustion as a typed CreditsExhaustedError.
    return mapCreditsExhaustion(
      this.rpcClient.call<AudioGenResult>(
        RundotGameMessageId.H5_AUDIO_GEN_GENERATE,
        params,
        -1,
      ),
    );
  }

  async getCompletedJobs(): Promise<AudioGenJobEvent[]> {
    return this.rpcClient.call<AudioGenJobEvent[]>(
      RundotGameMessageId.H5_POLL_COMPLETED_JOBS,
      { type: 'audioGen' },
    );
  }

  async listVoices(): Promise<ListVoicesResult> {
    return this.rpcClient.call<ListVoicesResult>(
      RundotGameMessageId.H5_AUDIO_GEN_LIST_VOICES,
    );
  }

  async designVoices(params: DesignVoicesParams): Promise<DesignVoicesResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<DesignVoicesResult>(
        RundotGameMessageId.H5_AUDIO_GEN_DESIGN_VOICES,
        params,
        -1,
      ),
    );
  }

  async saveDesignedVoice(params: SaveDesignedVoiceParams): Promise<SaveDesignedVoiceResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<SaveDesignedVoiceResult>(
        RundotGameMessageId.H5_AUDIO_GEN_SAVE_DESIGNED_VOICE,
        params,
        -1,
      ),
    );
  }
}
