﻿import { Host } from '../Host'
import { RundotGameAPI } from '../rundot-game-api/types'
import {
  AiApi,
  AiChatCompletionRequest,
  AiChatCompletionData,
  AiChatCompletionStreamChunk,
  AiChatCompletionStreamOptions,
  PromptCompletionRequest,
} from './AiApi'

export * from './AiApi'
export * from './RpcAiApi'
export * from './MockAiApi'

/**
 * @deprecated RundotGameAPI.ai is deprecated. Use RundotGameAPI.textGen instead.
 *
 * Wraps the underlying textGen implementation with a warn-once deprecation
 * notice so existing games keep working while migrating.
 */
export function initializeAi(rundotGameApi: RundotGameAPI, _host: Host): void {
  let warned = false
  const warn = (): void => {
    if (!warned) {
      console.warn('[RUN] RundotGameAPI.ai is deprecated. Use RundotGameAPI.textGen instead.')
      warned = true
    }
  }

  const deprecatedAi: AiApi = {
    async requestChatCompletionAsync(request: AiChatCompletionRequest): Promise<AiChatCompletionData> {
      warn()
      return rundotGameApi.textGen.requestChatCompletionAsync(request)
    },
    async getAvailableCompletionModels(): Promise<Array<string>> {
      warn()
      return rundotGameApi.textGen.getAvailableCompletionModels()
    },
    requestChatCompletionStreamAsync(
      request: AiChatCompletionRequest,
      options?: AiChatCompletionStreamOptions,
    ): AsyncIterable<AiChatCompletionStreamChunk> {
      warn()
      return rundotGameApi.textGen.requestChatCompletionStreamAsync(request, options)
    },
    async requestPromptCompletionAsync(request: PromptCompletionRequest): Promise<AiChatCompletionData> {
      warn()
      return rundotGameApi.textGen.requestPromptCompletionAsync(request)
    },
    requestPromptCompletionStreamAsync(
      request: PromptCompletionRequest,
      options?: AiChatCompletionStreamOptions,
    ): AsyncIterable<AiChatCompletionStreamChunk> {
      warn()
      return rundotGameApi.textGen.requestPromptCompletionStreamAsync(request, options)
    },
  }

  rundotGameApi.ai = deprecatedAi
}
