import type { CaptureConsent, CaptureConsentStatus } from './ClipsApi'
import type { CaptureConsentPort, CaptureConsentRequestOptions } from './CaptureConsentPort'

export class MockCaptureConsent implements CaptureConsentPort {
  constructor(private status: CaptureConsentStatus = 'granted') {}

  async get(): Promise<CaptureConsent> {
    return { status: this.status, canAskAgain: this.status !== 'denied' }
  }

  async request(_opts?: CaptureConsentRequestOptions): Promise<CaptureConsent> {
    this.status = 'granted'
    return { status: 'granted', canAskAgain: true }
  }

  async set(status: 'granted' | 'denied'): Promise<CaptureConsent> {
    this.status = status
    return { status, canAskAgain: status !== 'denied' }
  }
}
