import { Host } from '../Host'
import { RundotGameAPI } from '../rundot-game-api/types'

export * from './UgcApi'
export { RpcUgcApi } from './RpcUgcApi'
export { MockUgcApi } from './MockUgcApi'
// HttpUgcApi is intentionally NOT exported here.
// It depends on Firebase (via callRemoteFunction) and should only be imported by PlaygroundHost.
// This prevents Firebase from being bundled in production builds.

export function initializeUgc(rundotGameApiInstance: RundotGameAPI, host: Host): void {
  rundotGameApiInstance.ugc = host.ugc
}
