import type { Host } from '../Host'
import type { RundotGameAPI } from '../rundot-game-api/types'

export * from './VideoGenApi'
export { RpcVideoGenApi } from './RpcVideoGenApi'
export { MockVideoGenApi } from './MockVideoGenApi'
// HttpVideoGenApi is intentionally NOT exported here.
// It depends on Firebase and should only be imported by PlaygroundHost.
// This prevents Firebase from being bundled in production builds.

export function initializeVideoGen(rundotGameApi: RundotGameAPI, host: Host): void {
  rundotGameApi.videoGen = host.videoGen
}
