import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import {
  GetPagedScoresOptions,
  LeaderboardApi,
  PagedScoresResponse,
  GetPodiumScoresOptions,
  PodiumScoresResponse,
  PlayerRankResult,
  PlayerRankOptions,
  ScoreToken,
  SubmitScoreParams,
  SubmitScoreResult,
} from './LeaderboardApi'
import { computeScoreHash, mapSubmitScoreFailure } from './utils'
import { assertReplayWithinInlineCap } from './replaySize'

export class RpcLeaderboardApi implements LeaderboardApi {
  private readonly rpcClient: RpcClient
  /** Cache of score tokens for automatic hash computation */
  private tokenCache: Map<string, ScoreToken> = new Map()

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  /**
   * Create a score token for submitting a score.
   * Token is cached for automatic hash computation if score sealing is enabled.
   *
   * @param mode - Optional game mode
   * @returns Score token with sealing data if enabled
   */
  async createScoreToken(mode?: string): Promise<ScoreToken> {
    const token = await this.rpcClient.call<ScoreToken>(
      RundotGameMessageId.H5_LEADERBOARD_CREATE_SCORE_TOKEN,
      mode ? { mode } : {},
    )

    // Cache token with sealing data for auto-hash computation
    this.tokenCache.set(token.token, token)

    return token
  }

  /**
   * Submit a score to the leaderboard.
   * Automatically computes hash if score sealing is enabled and token was created via createScoreToken().
   *
   * @param params - Score submission parameters
   * @returns Submission result with acceptance status and rank
   * @throws Error if token not found in cache
   */
  async submitScore(params: SubmitScoreParams): Promise<SubmitScoreResult> {
    // Reject an over-cap replay before minting/consuming a token or hitting the
    // host, so the game gets an actionable error and no score is submitted.
    if (params.replay !== undefined) {
      assertReplayWithinInlineCap(params.replay)
    }

    let hash: string | undefined

    // If token provided, check if sealing is enabled and auto-compute hash
    if (params.token) {
      const cachedToken = this.tokenCache.get(params.token)

      if (!cachedToken) {
        throw new Error(
          'Invalid token: not found in cache. Did you call createScoreToken() first?'
        )
      }

      // Auto-compute hash if sealing enabled (token has nonce and secret)
      if (cachedToken.sealingNonce && cachedToken.sealingSecret) {
        hash = await computeScoreHash(
          params.score,
          params.duration,
          params.token,
          cachedToken.sealingNonce,
          cachedToken.sealingSecret,
        )
      }

      // Clean up used token from cache
      this.tokenCache.delete(params.token)
    }

    // Send to host/server (includes hash if sealing enabled)
    try {
      return await this.rpcClient.call<SubmitScoreResult>(
        RundotGameMessageId.H5_LEADERBOARD_SUBMIT_SCORE,
        {
          token: params.token,
          score: params.score,
          duration: params.duration,
          mode: params.mode,
          period: params.period,
          telemetry: params.telemetry,
          metadata: params.metadata,
          hash, // undefined if no sealing, computed if sealing enabled
          replay: params.replay, // recorded replay for a requiresReplay board
        },
      )
    } catch (error) {
      // Surface typed, non-throwing outcomes (identity change, replay rejection)
      // so the game can branch — e.g. flip its optimistic "pending verification"
      // state to rejected — instead of handling an opaque throw. Genuine failures
      // still throw.
      const mapped = mapSubmitScoreFailure(error)
      if (mapped) {
        return mapped
      }
      throw error
    }
  }

  getPagedScores(options?: GetPagedScoresOptions): Promise<PagedScoresResponse> {
    return this.rpcClient.call<PagedScoresResponse>(
      RundotGameMessageId.H5_LEADERBOARD_GET_PAGED_SCORES,
      options ?? {},
    )
  }

  getMyRank(options?: PlayerRankOptions): Promise<PlayerRankResult> {
    return this.rpcClient.call<PlayerRankResult>(
      RundotGameMessageId.H5_LEADERBOARD_GET_MY_RANK,
      options ?? {},
    )
  }

  getPodiumScores(options?: GetPodiumScoresOptions): Promise<PodiumScoresResponse> {
    return this.rpcClient.call<PodiumScoresResponse>(
      RundotGameMessageId.H5_LEADERBOARD_GET_PODIUM_SCORES,
      options ?? {},
    )
  }
}
