import {
  AiApi,
  AiChatCompletionData,
  AiChatCompletionRequest,
  AiChatCompletionStreamChunk,
  AiChatCompletionStreamOptions,
  PromptCompletionRequest,
  ToolUse,
} from './AiApi'

export class MockAiApi implements AiApi {
  async requestChatCompletionAsync(request: AiChatCompletionRequest): Promise<AiChatCompletionData> {
    if (request.tools !== undefined && request.tools.length > 0) {
      return this.buildMockToolCallResponse(request)
    }
    console.warn('[RUN] AI completion API not available in mock mode')
    throw new Error('AI completion API requires backend connection')
  }

  async getAvailableCompletionModels(): Promise<Array<string>> {
    console.warn('[RUN] AI models API not available in mock mode')
    throw new Error('AI models API requires backend connection')
  }

  /**
   * Canned stream so agent loops and tool flows can be exercised offline.
   *
   * Unlike the non-streaming sibling this does NOT throw: a streaming consumer
   * that cannot get a first chunk cannot be developed against the mock at all.
   * The text is prefixed `[mock]` so it is never mistaken for a real response.
   */
  requestChatCompletionStreamAsync(
    request: AiChatCompletionRequest,
    options?: AiChatCompletionStreamOptions,
  ): AsyncIterable<AiChatCompletionStreamChunk> {
    return this.mockCompletionStream(request, options)
  }

  async requestPromptCompletionAsync(_request: PromptCompletionRequest): Promise<AiChatCompletionData> {
    console.warn('[RUN] AI prompt completion API not available in mock mode')
    throw new Error('AI prompt completion API requires backend connection')
  }

  requestPromptCompletionStreamAsync(
    _request: PromptCompletionRequest,
    _options?: AiChatCompletionStreamOptions,
  ): AsyncIterable<AiChatCompletionStreamChunk> {
    return this.mockUnavailableStream('AI prompt completion')
  }

  /** Warn-now, throw-on-first-`next()` iterable shared by both mock stream methods. */
  private mockUnavailableStream(apiName: string): AsyncIterable<AiChatCompletionStreamChunk> {
    console.warn(`[RUN] ${apiName} API not available in mock mode`)
    return {
      [Symbol.asyncIterator]: (): AsyncIterator<AiChatCompletionStreamChunk> => ({
        next: async (): Promise<IteratorResult<AiChatCompletionStreamChunk>> => {
          throw new Error(`${apiName} API requires backend connection`)
        },
      }),
    }
  }

  /**
   * One tool call on the first pass, then text once a tool result comes back,
   * so a tool loop terminates instead of calling the same tool forever.
   */
  private async *mockCompletionStream(
    request: AiChatCompletionRequest,
    options?: AiChatCompletionStreamOptions,
  ): AsyncGenerator<AiChatCompletionStreamChunk> {
    const usage = { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 }
    const tool = request.tools?.[0]
    if (tool && !MockAiApi.hasToolResult(request)) {
      yield {
        type: 'tool_call_chunk',
        index: 0,
        id: `mock-tool-${tool.name}-1`,
        name: tool.name,
      }
      if (options?.signal?.aborted) return
      yield { type: 'tool_call_chunk', index: 0, argumentsDelta: '{}' }
      yield { type: 'done', finishReason: 'tool_calls', usage }
      return
    }
    for (const text of ['[mock] ', 'This is a canned response; ', 'connect a backend for a real one.']) {
      if (options?.signal?.aborted) return
      yield { type: 'delta', text }
    }
    yield { type: 'done', finishReason: 'stop', usage }
  }

  /** True once the conversation carries a tool result, i.e. a tool already ran. */
  private static hasToolResult(request: AiChatCompletionRequest): boolean {
    return request.messages.some(message =>
      Array.isArray(message.content) &&
      message.content.some(block => block.type === 'tool_result'))
  }

  /**
   * Deterministic canned response when the request supplies tools. Always
   * invokes the first tool in the list with an empty argument object — keeps
   * SDK consumers' tool-flow unit tests stable without a real provider.
   */
  private buildMockToolCallResponse(request: AiChatCompletionRequest): AiChatCompletionData {
    const tool = request.tools![0]
    const toolCalls: ToolUse[] = [{
      id: `mock-tool-${tool.name}-1`,
      name: tool.name,
      input: {},
    }]
    return {
      id: 'mock-completion-1',
      object: 'chat.completion',
      created: 0,
      model: request.model,
      choices: [{
        index: 0,
        message: { role: 'assistant', content: '', toolCalls },
        finish_reason: 'tool_calls',
      }],
      usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
    }
  }
}
