import {
  OnNotificationCallback,
  OnRequestCallback,
  OnResponseCallback,
  RpcNotification,
  RpcRequest,
  RpcResponse,
  RpcTransport,
  Subscription,
} from './rpc'
import { RundotGameMessageId } from './RundotGameMessageId'
import type { ProviderErrorDetail } from './errors'

export interface RundotGameMessage {
  type: string
  direction: string
  data?: {
    /**
     * Internal RPC correlation ID for request/response matching.
     *
     * ⚠️ WIRE PROTOCOL STABILITY WARNING ⚠️
     * This field name is part of the wire protocol between the SDK (H5 games) and the
     * host app (venus client). Both sides MUST agree on this field name.
     *
     * DO NOT RENAME THIS FIELD without coordinating a synchronized release of:
     * 1. packages/sdk (this file)
     * 2. venus/client H5MessageBus.ts
     *
     * Renaming breaks RPC - responses will not correlate and all API calls will timeout.
     */
    requestId?: string
    success?: boolean

    //NOTE(Zee): Some things send 'value' others send 'data'
    value?: any
    data?: any

    error?: string
    errorCode?: string
    retryAfterMs?: number
    /** Legacy flattened provider detail STRING — the field name is wire-frozen. */
    errorDetail?: string
    /** Structured provider rejection detail (new wire field; see errors.ts). */
    errorInfo?: ProviderErrorDetail

    script?: string
  }
  instanceId: string
  timestamp: number
  /**
   * Per-iframe nonce. Stamped on every outgoing frame by both the
   * SDK transport and the host. Receivers MUST drop any message where
   * `nonce !== expectedNonce`. Not flag-gated; always required when
   * `window.__rundotConfig.nonce` is populated.
   */
  nonce?: string
}

declare global {
  interface Window {
    _rundotGameInitState?: {
      poolId: string
      apiInjected: boolean
      gameInitialized: boolean
    }
    ReactNativeWebView?: {
      postMessage(message: string): void
    }
    rundotGame: {
      _config: {
        locale: string
        instanceId: string
        context?: any
        profile?: {
          id?: string
          username?: string
          name?: string
          displayName?: string
          avatarUrl?: string | null
          isAnonymous?: boolean
        }
        environment: {
          browserInfo?: {
            language: string
          }
        }
        _handlers: Record<string, any>
      }
      profile?: {
        id?: string
        username?: string
        avatarUrl?: string | null
        name?: string
        displayName?: string
        isAnonymous?: boolean
      } | null
      _fetchFromCdn: (url: string) => Promise<string>
    }
  }
}

export type OnRundotGameMessageCallback = (message: RundotGameMessage) => void

export class RundotGameTransport implements RpcTransport {
  private readonly messageHandler: (event: MessageEvent) => void

  private readonly onNotificationCallbacks: OnNotificationCallback[] = []
  private readonly onNotificationCallbacksToRemove: OnNotificationCallback[] =
    []

  private readonly onRundotGameMessageCallbacks: OnRundotGameMessageCallback[] = []
  private readonly onResponseCallbacks: OnResponseCallback[] = []
  private readonly onResponseCallbacksToRemove: OnResponseCallback[] = []

  private _instanceId: string | null = null
  private isStarted: boolean = false
  private isProcessingMessage: boolean = false

  constructor() {
    this.messageHandler = async (event) => {
      const cfg =
        (typeof window !== 'undefined' && (window as any).__rundotConfig) || null
      const expectedParentOrigin: string = (cfg && cfg.parentOrigin) || ''
      const expectedNonce: string = (cfg && cfg.nonce) || ''

      // RN bridge path: when posted via `ReactNativeWebView`, the receive
      // side is a synthetic event with `event.origin === ''` and no source.
      // Skip the origin check in that one case but still enforce nonce below.
      const isRnBridgeEvent =
        event.origin === '' && (event as any).source == null

      if (!isRnBridgeEvent) {
        if (expectedParentOrigin && event.origin !== expectedParentOrigin) {
          return
        }
        if (typeof window !== 'undefined' && event.source !== window.parent) {
          return
        }
      }

      this.isProcessingMessage = true

      let message: RundotGameMessage
      if (typeof event.data === 'string') {
        try {
          message = JSON.parse(event.data)
        } catch {
          this.isProcessingMessage = false
          return
        }
      } else {
        message = event.data as RundotGameMessage
      }

      if (!message) {
        this.logInfo('No message found. Ignoring message...')
        this.isProcessingMessage = false
        return
      }

      // Nonce required on every frame (not flag-gated).
      if (expectedNonce && (message as any).nonce !== expectedNonce) {
        this.isProcessingMessage = false
        return
      }

      //this.logInfo(`message received:\n${JSON.stringify(message, null, 2)}`)

      this.notifyRundotGameMessageReceived(message)

      if (
        message.type === RundotGameMessageId.PAUSE ||
        message.type === RundotGameMessageId.RESUME ||
        message.type === RundotGameMessageId.AWAKE ||
        message.type === RundotGameMessageId.SLEEP ||
        message.type === RundotGameMessageId.QUIT ||
        message.type === RundotGameMessageId.IDENTITY_CHANGED ||
        message.type === RundotGameMessageId.BACK_BUTTON
      ) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)

        // NOTE(Zee): This early return is dangerous here. we have to make sure isProcessingMessage is set to false!
        this.isProcessingMessage = false
        return
      }

      const messageData = message.data
      if (!messageData) {
        this.logWarn('No data found. Ignoring message...')
        this.isProcessingMessage = false
        return
      }

      if (message.type === RundotGameMessageId.H5_SIMULATION_UPDATE) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)
        this.isProcessingMessage = false
        return
      }

      if (message.type === RundotGameMessageId.H5_VIDEO_RESUME_FROM_NATIVE_PLAYBACK) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)
        this.isProcessingMessage = false
        return
      }

      if (message.type === RundotGameMessageId.H5_VIDEO_GEN_JOB_STARTED) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)
        this.isProcessingMessage = false
        return
      }

      if (message.type === RundotGameMessageId.NOTIFICATION_PARAMS_UPDATE) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)
        this.isProcessingMessage = false
        return
      }

      // Credits balance push (host → game): carries no requestId, so route it
      // as a notification rather than the default RPC-response path.
      if (message.type === RundotGameMessageId.CREDITS_BALANCE_UPDATE) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)
        this.isProcessingMessage = false
        return
      }

      // Host-owned activity dispatch: a native surface (Fire TV MediaSession,
      // and later Now Playing / Live Activities) issued a transport action for
      // an activity this game started. Carries no `requestId`, so route it as a
      // notification rather than down the default RPC-response path.
      if (message.type === RundotGameMessageId.ACTIVITY_ACTION) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)
        this.isProcessingMessage = false
        return
      }

      // Controller input (Tier 2): the host streams snapshots/connect events as
      // notifications carrying no `requestId`, so route them like the other
      // host→game pushes rather than the default RPC-response path.
      if (
        message.type === RundotGameMessageId.GAMEPAD_SNAPSHOT ||
        message.type === RundotGameMessageId.GAMEPAD_CONNECTED ||
        message.type === RundotGameMessageId.GAMEPAD_DISCONNECTED
      ) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)
        this.isProcessingMessage = false
        return
      }

      // AI streaming: host-emitted chunk / done / error notifications carry a
      // `streamId` payload that the SDK uses to fan messages back to the
      // correct in-flight iterator. Wired here (alongside the other
      // notification carve-outs) because the default response handling path
      // expects a `requestId` for RPC correlation, which these don't have.
      if (
        message.type === RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_CHUNK ||
        message.type === RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_DONE ||
        message.type === RundotGameMessageId.AI_CHAT_COMPLETION_STREAM_ERROR
      ) {
        const notification: RpcNotification = {
          type: 'rpc-notification',
          id: message.type,
          payload: message.data,
        }
        this.handleNotification(notification)
        this.isProcessingMessage = false
        return
      }

      const requestId = messageData.requestId
      if (!requestId) {
        this.logWarn('No requestId. Ignoring message...')
        this.isProcessingMessage = false
        return
      }

      if (message.type !== RundotGameMessageId.H5_RESPONSE) {
        this.logWarn(`Ignoring unknown message type: ${message.type}`)
        this.isProcessingMessage = false
        return
      }

      const success = messageData.success
      let error = undefined
      if (!success) {
        error = {
          message: messageData.error || 'Unknown error',
          ...(messageData.errorCode ? { code: messageData.errorCode } : {}),
          ...(messageData.errorDetail ? { detail: messageData.errorDetail } : {}),
          ...(messageData.errorInfo ? { errorDetail: messageData.errorInfo } : {}),
          ...(messageData.retryAfterMs !== undefined
            ? { retryAfterMs: messageData.retryAfterMs }
            : {}),
        }
      }

      // Result can be either inside value or data
      let result = messageData.value
      if (result === undefined) {
        result = messageData.data
      }

      const response: RpcResponse = {
        type: 'rpc-response',
        id: requestId,
        result: result,
        method: message.type,
        error: error,
      }

      await this.handleResponse(response)
      this.isProcessingMessage = false
    }
  }
  onNotification(callback: OnNotificationCallback): Subscription {
    this.onNotificationCallbacks.push(callback)
    return {
      unsubscribe: () => {
        if (this.isProcessingMessage) {
          this.onNotificationCallbacks.push(callback)
        } else {
          this.removeOnNotificationCallback(callback)
        }
      },
    }
  }

  onRequest(callback: OnRequestCallback): Subscription {
    throw new Error('Method not implemented.')
  }

  onResponse(callback: OnResponseCallback): Subscription {
    this.onResponseCallbacks.push(callback)
    return {
      unsubscribe: () => {
        if (this.isProcessingMessage) {
          this.onResponseCallbacksToRemove.push(callback)
        } else {
          this.removeOnResponseCallback(callback)
        }
      },
    }
  }

  public get instanceId(): string | null {
    return this._instanceId
  }

  public set instanceId(instanceId: string) {
    this._instanceId = instanceId
  }

  sendRequest(request: RpcRequest): void {
    const instanceId = this.instanceId || 'unknown'
    const method = request.method
    const args =
      request.args && typeof request.args === 'object'
        ? (request.args as Record<string, unknown>)
        : {}
    const message: RundotGameMessage = {
      type: method,
      direction: 'H5_TO_APP',
      data: {
        ...args,
        requestId: request.id,
      },
      instanceId: instanceId,
      timestamp: Date.now(),
    }
    this.sendRundotGameMessage(message)
  }

  sendRundotGameMessage(message: RundotGameMessage): void {
    const cfg =
      (typeof window !== 'undefined' && (window as any).__rundotConfig) || null
    const nonce = (cfg && cfg.nonce) || ''
    if (nonce && !message.nonce) {
      message.nonce = nonce
    }

    const messageAsString = JSON.stringify(message, null, 2)
    const reactNativeWebView = window.ReactNativeWebView
    if (reactNativeWebView) {
      // RN bridge: postMessage on the native bridge has no origin semantics.
      reactNativeWebView.postMessage(messageAsString)
    } else {
      // Target parent's specific origin instead of '*'. The '*'
      // fallback applies only when `__rundotConfig` is absent (mock/test
      // playground); in production the bootstrap always populates parentOrigin.
      const parentOrigin = (cfg && cfg.parentOrigin) || '*'
      window.parent.postMessage(messageAsString, parentOrigin)
    }
  }

  sendResponse(response: RpcResponse): void {
    throw new Error('Method not implemented.')
  }

  start() {
    if (this.isStarted) {
      return
    }
    this.isStarted = true
    window.addEventListener('message', this.messageHandler, true)
    this.logInfo(`Started`)
  }

  stop() {
    if (!this.isStarted) {
      return
    }
    this.isStarted = false
    window.removeEventListener('message', this.messageHandler)
    this.logInfo(`Stopped`)
  }

  private handleNotification(notification: RpcNotification): void {
    //this.logInfo('Notification received: ', notification.id)
    for (const callback of this.onNotificationCallbacks) {
      callback(notification)
    }

    for (const callback of this.onNotificationCallbacksToRemove) {
      this.removeOnNotificationCallback(callback)
    }
    this.onNotificationCallbacksToRemove.length = 0
  }

  private async handleResponse(response: RpcResponse): Promise<void> {
    for (const callback of this.onResponseCallbacks) {
      const consumed = await callback(response)
      if (consumed) {
        break
      }
    }

    for (const callback of this.onResponseCallbacksToRemove) {
      this.removeOnResponseCallback(callback)
    }
    this.onResponseCallbacksToRemove.length = 0
  }

  private removeOnResponseCallback(callback: OnResponseCallback): void {
    this.onResponseCallbacks.splice(
      this.onResponseCallbacks.indexOf(callback),
      1,
    )
  }

  private removeOnNotificationCallback(callback: OnNotificationCallback): void {
    this.onNotificationCallbacks.splice(
      this.onNotificationCallbacks.indexOf(callback),
      1,
    )
  }

  private logInfo(message: string, ...params: any[]) {}

  private logWarn(message: string, ...params: any[]) {
    console.warn(`[RUN:transport] ${message}`, ...params)
  }

  onRundotGameMessage(callback: OnRundotGameMessageCallback): Subscription {
    this.onRundotGameMessageCallbacks.push(callback)
    return {
      unsubscribe: () => {
        this.onRundotGameMessageCallbacks.splice(
          this.onRundotGameMessageCallbacks.indexOf(callback),
          1,
        )
      },
    }
  }

  private notifyRundotGameMessageReceived(message: RundotGameMessage) {
    for (const callback of this.onRundotGameMessageCallbacks) {
      callback(message)
    }
  }
}
