import {
  EntitlementApi,
  Entitlement,
  LedgerEntry,
} from './EntitlementApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { generateId } from '../utils/idGenerator'

export class RpcEntitlementApi implements EntitlementApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async listEntitlements(): Promise<Entitlement[]> {
    const response = await this.rpcClient.call<{ entitlements: Entitlement[] }>(
      RundotGameMessageId.H5_ENTITLEMENT_LIST,
      {},
    )
    return response.entitlements
  }

  async getQuantity(entitlementId: string): Promise<number> {
    const response = await this.rpcClient.call<{ quantity: number }>(
      RundotGameMessageId.H5_ENTITLEMENT_GET_QUANTITY,
      { entitlementId },
    )
    return response.quantity
  }

  async consumeEntitlement(
    entitlementId: string,
    quantity: number,
    callback?: (entitlement: Entitlement, referenceId: string) => void | Promise<void>,
    reason?: string,
    referenceId?: string,
  ): Promise<Entitlement> {
    referenceId = referenceId ?? generateId()
    const response = await this.rpcClient.call<{ entitlement: Entitlement }>(
      RundotGameMessageId.H5_ENTITLEMENT_CONSUME,
      { entitlementId, quantity, referenceId, reason },
    )
    const entitlement = response.entitlement
    if (callback) {
      try {
        await callback(entitlement, referenceId)
      } catch (e) {
        console.warn('[RUN] consumeEntitlement callback threw, but consume succeeded', e)
      }
    }
    return entitlement
  }

  async getLedger(entitlementId?: string, limit?: number, startAfter?: number): Promise<LedgerEntry[]> {
    const response = await this.rpcClient.call<{ ledger: LedgerEntry[] }>(
      RundotGameMessageId.H5_ENTITLEMENT_GET_LEDGER,
      { entitlementId, limit, startAfter },
    )
    return response.ledger
  }
}
