import { RundotGameAPI } from '../rundot-game-api/types'
import { Host } from '../Host'

export * from './LiveOpsApi'
export * from './resolveLiveOps'
export * from './RpcLiveOpsApi'
export * from './MockLiveOpsApi'
// HttpLiveOpsApi is intentionally NOT exported here.
// It depends on Firebase-adjacent playground transport and should only be
// imported by PlaygroundHost via direct import, keeping Firebase out of prod builds.

export function initializeLiveOps(rundotGameApi: RundotGameAPI, host: Host) {
  rundotGameApi.liveops = {
    getConfigAsync: (options) => host.liveops.getConfigAsync(options),
    getRawConfigAsync: (options) => host.liveops.getRawConfigAsync(options),
  }
}
