// packages/api/src/iap/RpcIapApi.ts
import {
  IapApi,
  SpendCurrencyOptions,
  SpendCurrencyResult,
  OpenStoreResult,
  RunSubscriptionsResponse,
  SubscriptionTier,
  GetSubscriptionsForTierRequest,
  PurchaseSubscriptionResponse,
  SubscriptionInterval,
  PurchaseSubscriptionRequest,
  IsPlayerSubscribedRequest,
  assertTierSupportsInterval,
  DirectPurchaseSku,
  GetCurrencyIconOptions,
} from './IapApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { LoadEmbeddedAssetsResponse } from '../shared-assets/RpcSharedAssetsApi'

export class RpcIapApi implements IapApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async getHardCurrencyBalance(): Promise<number> {
    const response = await this.rpcClient.call<number>(
      RundotGameMessageId.H5_IAP_GET_WALLET,
    )
    return response
  }

  async spendCurrency(
    productId: string,
    cost: number,
    options?: SpendCurrencyOptions,
  ): Promise<SpendCurrencyResult> {
    return await this.rpcClient.callT<
      IapSpendCurrencyRequest,
      SpendCurrencyResult
    >(RundotGameMessageId.H5_IAP_SPEND_CURRENCY, {
      amount: cost,
      productId: productId,
      screenName: options?.screenName,
      description: options?.description,
      beneficiaryId: options?.beneficiaryId,
      contentEntryId: options?.contentEntryId,
    }, -1)
  }

  /**
    * gets the subscription packages for a given tier. If no tier is provided, returns all subscription
    * packages for all tiers
    */
  async getSubscriptions(tier?: SubscriptionTier): Promise<RunSubscriptionsResponse> {
    return await this.rpcClient.callT<
      GetSubscriptionsForTierRequest,
      RunSubscriptionsResponse
    >(RundotGameMessageId.H5_IAP_GET_SUBSCRIPTIONS, { tier }, -1)
  }

  /**
    * triggers the checkout for a given subscription, identified by tier and interval.
    * Rejects with a `RundotApiError` (`UNSUPPORTED_SUBSCRIPTION_INTERVAL`) before
    * any checkout when the tier does not offer that interval — LITE is weekly-only.
    * @example
    * // will trigger the checkout for the weekly CORE subscription
    * await purchaseSubscription('CORE', 'weekly')
    */
  async purchaseSubscription(tier: SubscriptionTier, interval: SubscriptionInterval): Promise<PurchaseSubscriptionResponse> {
    assertTierSupportsInterval(tier, interval)
    return await this.rpcClient.callT<
      PurchaseSubscriptionRequest,
      PurchaseSubscriptionResponse
    >(RundotGameMessageId.H5_IAP_PURCHASE_SUBSCRIPTION, { tier, interval }, -1)
  }

  /**
    * Check if a user has a given subscription tier. If the user has a higher
    * subscription tier than the one being checked, this returns true.
    *
    * @example
    * // Returns true if the user has CORE, PLUS, PRIME, or ULTIMATE
    * await isUserSubscribed('CORE');
    *
    * // Returns true only if the user has ULTIMATE
    * await isUserSubscribed('ULTIMATE');
    */
  async isUserSubscribed(tier: SubscriptionTier): Promise<boolean> {
    return await this.rpcClient.callT<
      IsPlayerSubscribedRequest,
      boolean
    >(RundotGameMessageId.H5_IAP_GET_PLAYER_SUBSCRIPTION_INFO, { tier }, -1)
  }

  async openStore(): Promise<OpenStoreResult> {
    // No timeout — the user may spend an arbitrary amount of time in the store
    return await this.rpcClient.call<OpenStoreResult>(RundotGameMessageId.H5_IAP_OPEN_STORE, undefined, -1)
  }

  async getCurrencyIcon(options?: GetCurrencyIconOptions): Promise<LoadEmbeddedAssetsResponse> {
    return await this.rpcClient.callT<
      GetCurrencyIconOptions,
      LoadEmbeddedAssetsResponse
    >(RundotGameMessageId.H5_IAP_GET_CURRENCY_ICON, options ?? {})
  }


  async hasUserMadePurchase(): Promise<boolean> {
    return await this.rpcClient.call(RundotGameMessageId.H5_IAP_HAS_USER_MADE_PURCHASE)
  }

  async listDirectPurchaseSkus(gameId: string): Promise<DirectPurchaseSku[]> {
    return await this.rpcClient.callT<
      ListDirectPurchaseSkusRequest,
      DirectPurchaseSku[]
    >(RundotGameMessageId.H5_IAP_LIST_DIRECT_PURCHASE_SKUS, { gameId }, -1)
  }
}

interface IapSpendCurrencyRequest {
  amount: number // Required: amount to spend
  productId: string // Required: unique identifier for the item being purchased
  screenName?: string // Optional: screen/route name where purchase occurred
  description?: string // Optional: human-readable description shown in the host confirmation dialog
  beneficiaryId?: string // Optional: UGC creator profile id for revenue-share attribution
  contentEntryId?: string // Optional: story-level UGC entry id the spend buys; keys the Recombee purchase to that content
}

interface ListDirectPurchaseSkusRequest {
  gameId: string
}

