import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import type { CaptureConsent } from './ClipsApi'
import type { CaptureConsentPort, CaptureConsentRequestOptions } from './CaptureConsentPort'

export class RpcCaptureConsent implements CaptureConsentPort {
  constructor(private readonly rpcClient: RpcClient) {}

  get(): Promise<CaptureConsent> {
    return this.rpcClient.call<CaptureConsent>(
      RundotGameMessageId.CLIPS_GET_CAPTURE_CONSENT,
    )
  }

  request(opts?: CaptureConsentRequestOptions): Promise<CaptureConsent> {
    // No timeout (-1): the user may take a while in the native harness.
    return this.rpcClient.call<CaptureConsent>(
      RundotGameMessageId.CLIPS_REQUEST_CAPTURE_CONSENT,
      opts,
      -1,
    )
  }

  set(status: 'granted' | 'denied'): Promise<CaptureConsent> {
    return this.rpcClient.call<CaptureConsent>(
      RundotGameMessageId.CLIPS_SET_CAPTURE_CONSENT,
      { status },
    )
  }
}
