/**
 * RPC-backed UGC API implementation for RemoteHost
 *
 * All operations are forwarded to the React Native host via RPC messages.
 */
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import {
  UgcApi,
  UgcEntry,
  UgcCreateParams,
  UgcUpdateParams,
  UgcListParams,
  UgcListResponse,
  UgcCollaboratorParams,
  UgcMembersResponse,
  UgcBrowseParams,
  UgcBrowseResponse,
  UgcGetManyParams,
  UgcGetManyResponse,
  UgcReportParams,
  UgcCheckTextOptions,
  UgcCheckTextResult,
  UgcCountParams,
  UgcFollowCounts,
  UgcCrossAppBrowseParams,
  UgcCrossAppCreateParams,
  UgcCrossAppUpdateParams,
  UgcVotingApi,
  UgcVoteParams,
  UgcUnvoteParams,
  UgcVoteMutationResult,
  UgcMyVotesResponse,
  UgcVoteListParams,
  UgcVoteWinnersListParams,
  UgcVoteLeaderboardResponse,
  UgcVoteWinnersResponse,
  UgcRecommendationResponse,
  UgcCompositeRecommendationResponse,
} from './UgcApi'
import { checkText } from './checkText'

export class RpcUgcApi implements UgcApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async create(params: UgcCreateParams): Promise<UgcEntry> {
    return this.rpcClient.call<UgcEntry>(RundotGameMessageId.H5_UGC_CREATE, params)
  }

  async update(params: UgcUpdateParams): Promise<UgcEntry> {
    return this.rpcClient.call<UgcEntry>(RundotGameMessageId.H5_UGC_UPDATE, params)
  }

  async delete(id: string): Promise<void> {
    await this.rpcClient.call<void>(RundotGameMessageId.H5_UGC_DELETE, { id })
  }

  async get(id: string): Promise<UgcEntry | null> {
    return this.rpcClient.call<UgcEntry | null>(RundotGameMessageId.H5_UGC_GET, { id })
  }

  async listMine(params?: UgcListParams): Promise<UgcListResponse> {
    return this.rpcClient.call<UgcListResponse>(
      RundotGameMessageId.H5_UGC_LIST_MINE,
      params ?? {},
    )
  }

  async browse(params?: UgcBrowseParams): Promise<UgcBrowseResponse> {
    return this.rpcClient.call<UgcBrowseResponse>(
      RundotGameMessageId.H5_UGC_BROWSE,
      params ?? {},
    )
  }

  // Collaborators (multi-editor)

  async listShared(params?: UgcListParams): Promise<UgcListResponse> {
    return this.rpcClient.call<UgcListResponse>(
      RundotGameMessageId.H5_UGC_LIST_SHARED,
      params ?? {},
    )
  }

  async addCollaborator(params: UgcCollaboratorParams): Promise<void> {
    await this.rpcClient.call<void>(RundotGameMessageId.H5_UGC_ADD_MEMBER, params)
  }

  async removeCollaborator(params: UgcCollaboratorParams): Promise<void> {
    await this.rpcClient.call<void>(RundotGameMessageId.H5_UGC_REMOVE_MEMBER, params)
  }

  async listCollaborators(entryId: string): Promise<UgcMembersResponse> {
    return this.rpcClient.call<UgcMembersResponse>(
      RundotGameMessageId.H5_UGC_LIST_MEMBERS,
      { entryId },
    )
  }

  async getMany(params: UgcGetManyParams): Promise<UgcGetManyResponse> {
    return this.rpcClient.call<UgcGetManyResponse>(
      RundotGameMessageId.H5_UGC_GET_MANY,
      params,
    )
  }

  // Phase 2: Engagement methods

  async like(id: string): Promise<{ likeCount: number }> {
    return this.rpcClient.call<{ likeCount: number }>(
      RundotGameMessageId.H5_UGC_LIKE,
      { id },
    )
  }

  async unlike(id: string): Promise<{ likeCount: number }> {
    return this.rpcClient.call<{ likeCount: number }>(
      RundotGameMessageId.H5_UGC_UNLIKE,
      { id },
    )
  }

  async recordUse(id: string): Promise<{ useCount: number }> {
    return this.rpcClient.call<{ useCount: number }>(
      RundotGameMessageId.H5_UGC_RECORD_USE,
      { id },
    )
  }

  async report(params: UgcReportParams): Promise<void> {
    await this.rpcClient.call<void>(RundotGameMessageId.H5_UGC_REPORT, params)
  }

  // Runs locally in the game context — no RPC round trip to the host.
  async checkTextAsync(text: string, options?: UgcCheckTextOptions): Promise<UgcCheckTextResult> {
    return checkText(text, options)
  }

  async count(params?: UgcCountParams): Promise<{ count: number }> {
    return this.rpcClient.call<{ count: number }>(
      RundotGameMessageId.H5_UGC_COUNT,
      params ?? {},
    )
  }

  // Creator following

  async follow(targetProfileId: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_UGC_FOLLOW,
      { targetProfileId },
    )
  }

  async unfollow(targetProfileId: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_UGC_UNFOLLOW,
      { targetProfileId },
    )
  }

  async isFollowing(targetProfileId: string): Promise<{ isFollowing: boolean }> {
    return this.rpcClient.call<{ isFollowing: boolean }>(
      RundotGameMessageId.H5_UGC_IS_FOLLOWING,
      { targetProfileId },
    )
  }

  async getFollowCounts(targetProfileId: string): Promise<UgcFollowCounts> {
    return this.rpcClient.call<UgcFollowCounts>(
      RundotGameMessageId.H5_UGC_GET_FOLLOW_COUNTS,
      { targetProfileId },
    )
  }

  // Cross-app UGC

  async crossAppBrowse(params: UgcCrossAppBrowseParams): Promise<UgcBrowseResponse> {
    return this.rpcClient.call<UgcBrowseResponse>(
      RundotGameMessageId.H5_UGC_CROSS_APP_BROWSE,
      params,
    )
  }

  async crossAppGet(targetAppId: string, id: string): Promise<UgcEntry | null> {
    return this.rpcClient.call<UgcEntry | null>(
      RundotGameMessageId.H5_UGC_CROSS_APP_GET,
      { targetAppId, id },
    )
  }

  async crossAppGetMany(targetAppId: string, params: UgcGetManyParams): Promise<UgcGetManyResponse> {
    return this.rpcClient.call<UgcGetManyResponse>(
      RundotGameMessageId.H5_UGC_CROSS_APP_GET_MANY,
      { targetAppId, ...params },
    )
  }

  async crossAppCount(targetAppId: string, params?: UgcCountParams): Promise<{ count: number }> {
    return this.rpcClient.call<{ count: number }>(
      RundotGameMessageId.H5_UGC_CROSS_APP_COUNT,
      { targetAppId, ...(params ?? {}) },
    )
  }

  async crossAppCreate(params: UgcCrossAppCreateParams): Promise<UgcEntry> {
    return this.rpcClient.call<UgcEntry>(
      RundotGameMessageId.H5_UGC_CROSS_APP_CREATE,
      params,
    )
  }

  async crossAppUpdate(params: UgcCrossAppUpdateParams): Promise<UgcEntry> {
    return this.rpcClient.call<UgcEntry>(
      RundotGameMessageId.H5_UGC_CROSS_APP_UPDATE,
      params,
    )
  }

  async crossAppDelete(targetAppId: string, id: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_UGC_CROSS_APP_DELETE,
      { targetAppId, id },
    )
  }

  // Recommendations

  async getUserRecommendation(count: number, filter?: string): Promise<UgcRecommendationResponse> {
    return this.rpcClient.call<UgcRecommendationResponse>(
      RundotGameMessageId.H5_UGC_GET_USER_RECOMMENDATION,
      { count, filter },
    )
  }

  async getItemRecommendation(ugcId: string, count: number, filter?: string): Promise<UgcRecommendationResponse> {
    return this.rpcClient.call<UgcRecommendationResponse>(
      RundotGameMessageId.H5_UGC_GET_ITEM_RECOMMENDATION,
      { ugcId, count, filter },
    )
  }

  async getCompositeRecommendation(count: number, sourceFilter?: string, resultFilter?: string): Promise<UgcCompositeRecommendationResponse> {
    return this.rpcClient.call<UgcCompositeRecommendationResponse>(
      RundotGameMessageId.H5_UGC_GET_COMPOSITE_RECOMMENDATION,
      { count, sourceFilter, resultFilter },
    )
  }

  async getMoreRecommendations(origRecommId: string, count: number): Promise<UgcRecommendationResponse> {
    return this.rpcClient.call<UgcRecommendationResponse>(
      RundotGameMessageId.H5_UGC_GET_MORE_RECOMMENDATIONS,
      { origRecommId, count },
    )
  }

  async addDetailView(ugcId: string, recommId?: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_UGC_ADD_DETAIL_VIEW,
      { ugcId, recommId },
    )
  }

  async addRating(ugcId: string, rating: number, recommId?: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_UGC_ADD_RATING,
      { ugcId, rating, recommId },
    )
  }

  async addCartAddition(ugcId: string, recommId?: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_UGC_ADD_CART_ADDITION,
      { ugcId, recommId },
    )
  }

  async setViewPortion(ugcId: string, portion: number, recommId?: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_UGC_SET_VIEW_PORTION,
      { ugcId, portion, recommId },
    )
  }

  // Weekly voting

  readonly voting: UgcVotingApi = {
    vote: (params: UgcVoteParams): Promise<UgcVoteMutationResult> => {
      return this.rpcClient.call<UgcVoteMutationResult>(
        RundotGameMessageId.H5_UGC_VOTING_VOTE,
        params,
      )
    },
    unvote: (params: UgcUnvoteParams): Promise<UgcVoteMutationResult> => {
      return this.rpcClient.call<UgcVoteMutationResult>(
        RundotGameMessageId.H5_UGC_VOTING_UNVOTE,
        params,
      )
    },
    getMyVotes: (): Promise<UgcMyVotesResponse> => {
      return this.rpcClient.call<UgcMyVotesResponse>(
        RundotGameMessageId.H5_UGC_VOTING_GET_MY_VOTES,
        {},
      )
    },
    getLeaderboard: (params?: UgcVoteListParams): Promise<UgcVoteLeaderboardResponse> => {
      return this.rpcClient.call<UgcVoteLeaderboardResponse>(
        RundotGameMessageId.H5_UGC_VOTING_GET_LEADERBOARD,
        params ?? {},
      )
    },
    getWinners: (params?: UgcVoteWinnersListParams): Promise<UgcVoteWinnersResponse> => {
      return this.rpcClient.call<UgcVoteWinnersResponse>(
        RundotGameMessageId.H5_UGC_VOTING_GET_WINNERS,
        params ?? {},
      )
    },
  }
}
