import { RundotApiError } from '../errors'
import { utf8ByteLength } from '../utils/utf8'
import { SubmitScoreParams } from './LeaderboardApi'

// Mirrors server/game-server/src/utils/h5LeaderboardValidation.ts and the default
// bounds in h5leaderboard.service.ts. The mock has no per-mode config, so it uses
// the server defaults. Throws RundotApiError to match the production surface
// (the game observes a RundotApiError for leaderboard rejections).
const MIN_SCORE = 0
const MAX_SCORE = 999_999_999
const MIN_DURATION_SEC = 10
const MAX_DURATION_SEC = 3600
const MAX_METADATA_BYTES = 20 * 1024

export function validateSubmitScore(params: SubmitScoreParams): void {
  const { score, duration, metadata } = params

  if (typeof score !== 'number' || Number.isNaN(score)) {
    throw new RundotApiError('INVALID_ARGUMENT', 'Score must be a valid number', 400)
  }
  if (score < MIN_SCORE || score > MAX_SCORE) {
    throw new RundotApiError('INVALID_ARGUMENT', 'Score out of bounds', 400)
  }

  // duration is a REQUIRED field on SubmitScoreParams; prod's ensureValidDuration
  // rejects undefined (→ not finite). Validate unconditionally to match.
  if (!Number.isFinite(duration) || duration < 0) {
    throw new RundotApiError('INVALID_ARGUMENT', 'Duration must be a positive number', 400)
  }
  if (duration < MIN_DURATION_SEC || duration > MAX_DURATION_SEC) {
    throw new RundotApiError('INVALID_ARGUMENT', 'Duration out of bounds', 400)
  }

  if (metadata !== undefined && metadata !== null) {
    // Mirrors normalizeMetadata in h5LeaderboardValidation.ts: reject non-plain
    // objects up front, then verify JSON-serializability (BigInt throws) and that
    // the value round-trips to an object (a Date serializes to a string). Without
    // the try/catch a BigInt would surface a raw TypeError instead of the
    // production RundotApiError.
    if (typeof metadata !== 'object' || Array.isArray(metadata)) {
      throw new RundotApiError('INVALID_ARGUMENT', 'Metadata must be a plain object', 400)
    }
    let serialized: string
    try {
      serialized = JSON.stringify(metadata)
    } catch {
      throw new RundotApiError('INVALID_ARGUMENT', 'Metadata must be JSON serializable', 400)
    }
    // Order matches normalizeMetadata exactly: size check BEFORE the reparse
    // object-check (so an object whose toJSON() returns a >20KB string surfaces
    // 'exceeds 20KB limit', not 'must be an object').
    if (utf8ByteLength(serialized) > MAX_METADATA_BYTES) {
      throw new RundotApiError('INVALID_ARGUMENT', 'Metadata exceeds 20KB limit', 400)
    }
    const reparsed = JSON.parse(serialized)
    if (typeof reparsed !== 'object' || reparsed === null || Array.isArray(reparsed)) {
      throw new RundotApiError('INVALID_ARGUMENT', 'Metadata must be an object', 400)
    }
  }
}
