import { mockLog } from '../MockDebug'
import { RundotApiError } from '../errors'

const TAG = 'Mock Shop'

// Mirrors RefundReasonCode in server/cloud-run/src/types/shop.ts.
const VALID_REFUND_REASONS = new Set([
  'not_as_expected',
  'accidental_purchase',
  'technical_issue',
  'changed_mind',
  'other',
])

