import {
  SpriteGenApi,
  SpriteGenParams,
  SpriteGenResult,
  AnimateSpriteParams,
  AnimateSpriteResult,
  CharacterAnimateParams,
  CharacterWorkflow,
  SpriteGenCosts,
  SpriteGenJobEvent,
} from './SpriteGenApi';
import { RpcClient } from '../rpc';
import { RundotGameMessageId } from '../RundotGameMessageId';
import { mapCreditsExhaustion } from '../credits/CreditsApi';

export class RpcSpriteGenApi implements SpriteGenApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async generate(params: SpriteGenParams): Promise<SpriteGenResult> {
    // Surface player creator-credit exhaustion as a typed CreditsExhaustedError.
    return mapCreditsExhaustion(
      this.rpcClient.call<SpriteGenResult>(
        RundotGameMessageId.H5_SPRITE_GEN_GENERATE,
        params,
        -1,
      ),
    );
  }

  async animate(params: AnimateSpriteParams): Promise<AnimateSpriteResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<AnimateSpriteResult>(
        RundotGameMessageId.H5_SPRITE_GEN_ANIMATE,
        params,
        -1,
      ),
    );
  }

  async characterAnimate(params: CharacterAnimateParams): Promise<{ jobId: string }> {
    return this.rpcClient.call<{ jobId: string }>(
      RundotGameMessageId.H5_SPRITE_GEN_CHARACTER_ANIMATE,
      params,
      -1,
    );
  }

  async listCharacterWorkflows(): Promise<CharacterWorkflow[]> {
    return this.rpcClient.call<CharacterWorkflow[]>(
      RundotGameMessageId.H5_SPRITE_GEN_LIST_CHARACTER_WORKFLOWS,
      {},
    );
  }

  async listModels(): Promise<unknown> {
    return this.rpcClient.call<unknown>(
      RundotGameMessageId.H5_SPRITE_GEN_LIST_MODELS,
      {},
    );
  }

  async getCosts(): Promise<SpriteGenCosts> {
    return this.rpcClient.call<SpriteGenCosts>(
      RundotGameMessageId.H5_SPRITE_GEN_GET_COSTS,
      {},
    );
  }

  async getCompletedJobs(): Promise<SpriteGenJobEvent[]> {
    return this.rpcClient.call<SpriteGenJobEvent[]>(
      RundotGameMessageId.H5_POLL_COMPLETED_JOBS,
      { type: 'spriteGen' },
    );
  }
}
