﻿import {
  CollectRecipeResult,
  ExecuteRecipeOptions,
  ExecuteRecipeResponse,
  ExecuteScopedRecipeResult,
  ExecuteScopedRecipeOptions,
  GetActiveRunsOptions,
  GetAvailableRecipesOptions,
  GetAvailableRecipesResult,
  GetBatchRecipeRequirements,
  Recipe,
  SimulationApi,
  SimulationAvailableItem,
  SimulationAssignment,
  SimulationBatchOperation,
  SimulationBatchOperationsResult,
  SimulationPowerPreview,
  SimulationRunSummary,
  SimulationSlotMutationResult,
  SimulationSlotValidationResult,
  SimulationSlotContainer,
  SimulationState,
  SimulationPersonalState,
  SimulationRoomState,
  TriggerRecipeChainOptions,
  ResetStateOptions,
  ResetStateResult,
} from './SimulationApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import {
  RecipeRequirementResult,
  RundotGameSimulationConfig,
  SimulationSubscribeOptions,
  SimulationUpdateData,
} from '../rundot-game-api/types'
import { generateId } from '../utils/idGenerator'

interface ResolveFieldValueResponse {
  value: unknown
}

interface SimulationUpdateNotification {
  subscriptionId: string
  updates: SimulationUpdateData
}

interface StateResponseExtension {
  configuration?: RundotGameSimulationConfig
}

interface PersonalStateResponse extends SimulationPersonalState, StateResponseExtension {}

interface RoomStateResponse extends SimulationRoomState, StateResponseExtension {}

type GetStateResponse = PersonalStateResponse | RoomStateResponse

export class RpcSimulationApi implements SimulationApi {
  private readonly rpcClient: RpcClient
  private _simulationConfig: RundotGameSimulationConfig | null = null
  private readonly subscriptionCallbacks = new Map<
    string,
    (data: SimulationUpdateData) => void
  >()

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
    this.rpcClient.onNotification(
      RundotGameMessageId.H5_SIMULATION_UPDATE,
      this.handleSimulationUpdate.bind(this),
    )
  }

  isEnabled(): boolean {
    return true
  }

  async validateSlotAssignmentAsync(
    containerId: string,
    slotId: string,
    itemId: string,
  ): Promise<SimulationSlotValidationResult> {
    return this.rpcClient.call<SimulationSlotValidationResult>(
      RundotGameMessageId.H5_SIMULATION_VALIDATE_ASSIGNMENT,
      {
        containerId,
        slotId,
        itemId,
      },
    )
  }

  async subscribeAsync(
    options: SimulationSubscribeOptions,
  ): Promise<() => void> {
    this.ensureValidSubscribeOptions(options)

    const subscriptionId = generateId()
    this.subscriptionCallbacks.set(subscriptionId, options.onUpdate)

    try {
      await this.rpcClient.call(RundotGameMessageId.H5_SIMULATION_SUBSCRIBE, {
        subscriptionId,
        entities: options.entities,
        tags: options.tags,
        activeRuns: options.activeRuns,
        roomId: options.roomId,
      })
    } catch (error) {
      this.subscriptionCallbacks.delete(subscriptionId)
      throw error
    }

    let unsubscribed = false
    return () => {
      if (unsubscribed) {
        return
      }
      unsubscribed = true

      this.subscriptionCallbacks.delete(subscriptionId)

      // Fire-and-forget cleanup: the SDK does not need (and cannot
      // meaningfully recover from) an unsubscribe response. Using
      // notify() avoids spurious 30s timeout errors when the iframe is
      // throttled (e.g. backgrounded tab) and the host's response is
      // late.
      this.rpcClient.notify(RundotGameMessageId.H5_SIMULATION_UNSUBSCRIBE, {
        subscriptionId,
      })
    }
  }

  executeBatchOperationsAsync(
    operations: Array<SimulationBatchOperation>,
    validateOnly?: boolean,
  ): Promise<SimulationBatchOperationsResult> {
    return this.rpcClient.call<SimulationBatchOperationsResult>(
      RundotGameMessageId.H5_SIMULATION_BATCH_OPERATIONS,
      {
        operations,
        validateOnly,
      },
    )
  }
  async getAvailableItemsAsync(
    containerId: string,
    slotId: string,
  ): Promise<SimulationAvailableItem[]> {
    const response = await this.rpcClient.call<{
      availableItems?: SimulationAvailableItem[]
    }>(
      RundotGameMessageId.H5_SIMULATION_GET_AVAILABLE_ITEMS,
      {
        containerId,
        slotId,
      },
    )
    return response.availableItems || []
  }
  calculatePowerPreviewAsync(
    containerId: string,
    slotId: string,
    candidateItemId: string,
  ): Promise<SimulationPowerPreview> {
    return this.rpcClient.call<SimulationPowerPreview>(
      RundotGameMessageId.H5_SIMULATION_CALCULATE_POWER_PREVIEW,
      {
        containerId,
        slotId,
        candidateItemId,
      },
    )
  }
  assignItemToSlotAsync(
    containerId: string,
    slotId: string,
    itemId: string,
  ): Promise<SimulationSlotMutationResult> {
    return this.rpcClient.call<SimulationSlotMutationResult>(
      RundotGameMessageId.H5_SIMULATION_ASSIGN_ITEM,
      {
        containerId,
        slotId,
        itemId,
      },
    )
  }

  removeItemFromSlotAsync(
    containerId: string,
    slotId: string,
  ): Promise<SimulationSlotMutationResult> {
    return this.rpcClient.call<SimulationSlotMutationResult>(
      RundotGameMessageId.H5_SIMULATION_REMOVE_ITEM,
      {
        containerId,
        slotId,
      },
    )
  }

  async getSlotContainersAsync(): Promise<SimulationSlotContainer[]> {
    const response = await this.rpcClient.call<{
      containers?: SimulationSlotContainer[]
    }>(
      RundotGameMessageId.H5_SIMULATION_GET_CONTAINERS,
      {},
    )
    return response.containers || []
  }

  async getSlotAssignmentsAsync(
    containerId: string,
  ): Promise<SimulationAssignment[]> {
    const response = await this.rpcClient.call<
      SimulationAssignment[] | { assignments?: SimulationAssignment[] }
    >(
      RundotGameMessageId.H5_SIMULATION_GET_ASSIGNMENTS,
      {
        containerId,
      },
    )
    // Server returns raw array, not wrapped in .assignments property
    return Array.isArray(response)
      ? response
      : response.assignments || []
  }

  async getStateAsync(roomId?: string): Promise<SimulationState> {
    const response = await this.rpcClient.call<GetStateResponse>(
      RundotGameMessageId.H5_SIMULATION_GET_STATE,
      {
        roomId: roomId,
      },
    )

    // Cache configuration if included in response
    if (response.configuration) {
      this._simulationConfig = response.configuration
    }
    return response
  }

  async getConfigAsync(roomId?: string): Promise<RundotGameSimulationConfig> {
    if (this._simulationConfig) {
      return this._simulationConfig
    }

    // Fetch configuration directly
    const config = await this.rpcClient.call<RundotGameSimulationConfig>(
      RundotGameMessageId.H5_SIMULATION_GET_CONFIG,
      {
        roomId,
      },
    )
    if (config) {
      this._simulationConfig = config
      return config
    }

    throw new Error('No simulation configuration available')
  }

  executeRecipeAsync(
    recipeId: string,
    inputs?: Record<string, unknown>,
    options?: ExecuteRecipeOptions,
  ): Promise<ExecuteRecipeResponse> {
    return this.rpcClient.call<ExecuteRecipeResponse>(
      RundotGameMessageId.H5_SIMULATION_EXECUTE_RECIPE,
      {
        recipeId: recipeId,
        inputs: inputs,
        roomId: options?.roomId,
        batchAmount: options?.batchAmount,
        allowPartialBatch: options?.allowPartialBatch,
        entity: options?.entity,
        nonce: options?.nonce,
      },
    )
  }

  collectRecipeAsync(runId: string): Promise<CollectRecipeResult> {
    return this.rpcClient.call(RundotGameMessageId.H5_SIMULATION_COLLECT_RECIPE, {
      runId: runId,
    })
  }

  resetStateAsync(options?: ResetStateOptions): Promise<ResetStateResult> {
    return this.rpcClient.call<ResetStateResult>(
      RundotGameMessageId.H5_SIMULATION_RESET_STATE,
      {
        initializeRecipe: options?.initializeRecipe,
      },
    )
  }

  getActiveRunsAsync(
    options?: GetActiveRunsOptions,
  ): Promise<SimulationRunSummary[]> {
    return this.rpcClient.call<SimulationRunSummary[]>(
      RundotGameMessageId.H5_SIMULATION_GET_ACTIVE_RUNS,
      {
        roomId: options?.roomId,
      },
    )
  }

  executeScopedRecipeAsync(
    recipeId: string,
    entity: string,
    inputs?: Record<string, unknown>,
    options?: ExecuteScopedRecipeOptions,
  ): Promise<ExecuteScopedRecipeResult> {
    return this.rpcClient.call(
      RundotGameMessageId.H5_SIMULATION_EXECUTE_SCOPED_RECIPE,
      {
        recipeId: recipeId,
        entity: entity,
        inputs: inputs,
        roomId: options?.roomId ?? null,
        options,
      },
    )
  }

  getAvailableRecipesAsync(
    options?: GetAvailableRecipesOptions,
  ): Promise<GetAvailableRecipesResult> {
    return this.rpcClient.call(
      RundotGameMessageId.H5_SIMULATION_GET_AVAILABLE_RECIPES,
      {
        roomId: options?.roomId || null,
        includeActorRecipes: options?.includeActorRecipes || false,
      },
    )
  }

  getRecipeRequirementsAsync(
    recipe: Recipe,
  ): Promise<RecipeRequirementResult> {
    return this.rpcClient.call<RecipeRequirementResult>(
      RundotGameMessageId.H5_SIMULATION_GET_RECIPE_REQUIREMENTS,
      {
        recipeId: recipe.recipeId,
        nonce: recipe.nonce,
        entity: recipe.entity,
        batchAmount: recipe.batchAmount,
      },
    )
  }

  getBatchRecipeRequirementsAsync(
    recipes: Recipe[],
  ): Promise<GetBatchRecipeRequirements> {
    return this.rpcClient.call<GetBatchRecipeRequirements>(
      RundotGameMessageId.H5_SIMULATION_GET_BATCH_RECIPE_REQUIREMENTS,
      {
        recipes,
      },
    )
  }

  triggerRecipeChainAsync(
    recipeId: string,
    options?: TriggerRecipeChainOptions,
  ): Promise<ExecuteRecipeResponse> {
    return this.rpcClient.call<ExecuteRecipeResponse>(
      RundotGameMessageId.H5_SIMULATION_TRIGGER_RECIPE_CHAIN,
      {
        triggerRecipeId: recipeId,
        context: options?.context,
        roomId: options?.roomId,
      },
    )
  }

  getEntityMetadataAsync(
    entityId: string,
  ): Promise<Record<string, unknown>> {
    return this.rpcClient.call<Record<string, unknown>>(
      RundotGameMessageId.H5_SIMULATION_GET_ENTITY_METADATA,
      {
        entityId,
      },
    )
  }

  async resolveFieldValueAsync(
    entityId: string,
    fieldPath: string,
    entity?: string,
  ): Promise<unknown> {
    const response = await this.rpcClient.call<ResolveFieldValueResponse>(
      RundotGameMessageId.H5_SIMULATION_RESOLVE_VALUE,
      {
        entityId,
        fieldPath,
        entity,
      },
    )
    // Extract primitive value from server response wrapper
    return response.value
  }

  private handleSimulationUpdate(
    notification: SimulationUpdateNotification,
  ): void {
    if (!notification || !notification.subscriptionId) {
      console.warn('[RUN] Received malformed simulation update')
      return
    }

    const callback = this.subscriptionCallbacks.get(notification.subscriptionId)
    if (!callback) {
      console.warn(
        '[RUN] Received update for unknown subscription:',
        notification.subscriptionId,
      )
      return
    }

    try {
      callback(notification.updates)
    } catch (error) {
      console.error('[RUN] Error in simulation subscription callback', error)
    }
  }

  private ensureValidSubscribeOptions(
    options: unknown,
  ): asserts options is SimulationSubscribeOptions {
    if (typeof options !== 'object' || options === null) {
      throw new Error('Simulation subscribe requires an options object')
    }

    const opts = options as Record<string, unknown>

    if (typeof opts.onUpdate !== 'function') {
      throw new Error('Simulation subscribe requires an onUpdate callback')
    }

    const hasFilter =
      (Array.isArray(opts.entities) && opts.entities.length > 0) ||
      (Array.isArray(opts.tags) && opts.tags.length > 0) ||
      Boolean(opts.activeRuns)

    if (!hasFilter) {
      throw new Error(
        'Simulation subscribe requires at least one filter (entities, tags, activeRuns)',
      )
    }
  }
}
