import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import type {
  AppApi,
  AppRole,
  AdminUgcApi,
  AdminImageGenApi,
  AdminVideoGenApi,
  AdminSpriteGenApi,
  AdminAudioGenApi,
  AdminThreeDGenApi,
  ImageGenEntry,
  ImageGenReport,
  VideoGenEntry,
  VideoGenReport,
  SpriteGenEntry,
  SpriteGenReport,
  AudioGenEntry,
  AudioGenReport,
  ThreeDGenEntry,
  ThreeDGenReport,
  ReleaseNote,
} from './AppApi'
import type { LaunchIntent, ResolveLaunchIntentOptions } from './LaunchIntent'
import { RpcAdminUgcApi } from './RpcAdminUgcApi'
import { createRpcAdminGenApi } from './adminGen'

export class RpcAppApi implements AppApi {
  private readonly rpcClient: RpcClient
  readonly adminUgc: AdminUgcApi
  readonly adminImageGen: AdminImageGenApi
  readonly adminVideoGen: AdminVideoGenApi
  readonly adminSpriteGen: AdminSpriteGenApi
  readonly adminAudioGen: AdminAudioGenApi
  readonly adminThreeDGen: AdminThreeDGenApi

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
    this.adminUgc = new RpcAdminUgcApi(rpcClient)
    this.adminImageGen = createRpcAdminGenApi<ImageGenEntry, ImageGenReport>(rpcClient, {
      browse: RundotGameMessageId.H5_APP_ADMIN_IMAGEGEN_BROWSE,
      removeEntry: RundotGameMessageId.H5_APP_ADMIN_IMAGEGEN_REMOVE_ENTRY,
      listReports: RundotGameMessageId.H5_APP_ADMIN_IMAGEGEN_LIST_REPORTS,
      resolveReport: RundotGameMessageId.H5_APP_ADMIN_IMAGEGEN_RESOLVE_REPORT,
    })
    this.adminVideoGen = createRpcAdminGenApi<VideoGenEntry, VideoGenReport>(rpcClient, {
      browse: RundotGameMessageId.H5_APP_ADMIN_VIDEOGEN_BROWSE,
      removeEntry: RundotGameMessageId.H5_APP_ADMIN_VIDEOGEN_REMOVE_ENTRY,
      listReports: RundotGameMessageId.H5_APP_ADMIN_VIDEOGEN_LIST_REPORTS,
      resolveReport: RundotGameMessageId.H5_APP_ADMIN_VIDEOGEN_RESOLVE_REPORT,
    })
    this.adminSpriteGen = createRpcAdminGenApi<SpriteGenEntry, SpriteGenReport>(rpcClient, {
      browse: RundotGameMessageId.H5_APP_ADMIN_SPRITEGEN_BROWSE,
      removeEntry: RundotGameMessageId.H5_APP_ADMIN_SPRITEGEN_REMOVE_ENTRY,
      listReports: RundotGameMessageId.H5_APP_ADMIN_SPRITEGEN_LIST_REPORTS,
      resolveReport: RundotGameMessageId.H5_APP_ADMIN_SPRITEGEN_RESOLVE_REPORT,
    })
    this.adminAudioGen = createRpcAdminGenApi<AudioGenEntry, AudioGenReport>(rpcClient, {
      browse: RundotGameMessageId.H5_APP_ADMIN_AUDIOGEN_BROWSE,
      removeEntry: RundotGameMessageId.H5_APP_ADMIN_AUDIOGEN_REMOVE_ENTRY,
      listReports: RundotGameMessageId.H5_APP_ADMIN_AUDIOGEN_LIST_REPORTS,
      resolveReport: RundotGameMessageId.H5_APP_ADMIN_AUDIOGEN_RESOLVE_REPORT,
    })
    this.adminThreeDGen = createRpcAdminGenApi<ThreeDGenEntry, ThreeDGenReport>(rpcClient, {
      browse: RundotGameMessageId.H5_APP_ADMIN_THREEDGEN_BROWSE,
      removeEntry: RundotGameMessageId.H5_APP_ADMIN_THREEDGEN_REMOVE_ENTRY,
      listReports: RundotGameMessageId.H5_APP_ADMIN_THREEDGEN_LIST_REPORTS,
      resolveReport: RundotGameMessageId.H5_APP_ADMIN_THREEDGEN_RESOLVE_REPORT,
    })
  }

  async getMyRole(): Promise<AppRole> {
    const result = await this.rpcClient.call<{ role: AppRole }>(
      RundotGameMessageId.H5_APP_GET_MY_ROLE,
      {},
    )
    return result.role
  }

  async resolveLaunchIntent(
    options?: ResolveLaunchIntentOptions,
  ): Promise<LaunchIntent> {
    return this.rpcClient.call<LaunchIntent>(
      RundotGameMessageId.H5_RESOLVE_LAUNCH_INTENT,
      { maxWaitMs: options?.maxWaitMs },
    )
  }

  async getReleaseNotesAsync(): Promise<ReleaseNote[]> {
    const result = await this.rpcClient.call<{ releaseNotes: ReleaseNote[] }>(
      RundotGameMessageId.GET_RELEASE_NOTES,
    )
    return result.releaseNotes
  }

  async openReleaseNotesAsync(): Promise<void> {
    await this.rpcClient.call(RundotGameMessageId.OPEN_RELEASE_NOTES)
  }
}
