import {
  ThreeDGenApi,
  ThreeDGenParams,
  ThreeDGenResult,
  RemeshParams,
  RemeshResult,
  RigParams,
  RigResult,
  AnimateParams,
  AnimateResult,
  ThreeDGenJobEvent,
} from './ThreeDGenApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { mapCreditsExhaustion } from '../credits/CreditsApi'

export class RpcThreeDGenApi implements ThreeDGenApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async generate(params: ThreeDGenParams): Promise<ThreeDGenResult> {
    // Surface player creator-credit exhaustion as a typed CreditsExhaustedError.
    return mapCreditsExhaustion(
      this.rpcClient.call<ThreeDGenResult>(
        RundotGameMessageId.H5_THREE_D_GEN_GENERATE,
        params,
        -1,
      ),
    )
  }

  async remesh(params: RemeshParams): Promise<RemeshResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<RemeshResult>(
        RundotGameMessageId.H5_THREE_D_GEN_REMESH,
        params,
        -1,
      ),
    )
  }

  async rig(params: RigParams): Promise<RigResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<RigResult>(
        RundotGameMessageId.H5_THREE_D_GEN_RIG,
        params,
        -1,
      ),
    )
  }

  async animate(params: AnimateParams): Promise<AnimateResult> {
    return mapCreditsExhaustion(
      this.rpcClient.call<AnimateResult>(
        RundotGameMessageId.H5_THREE_D_GEN_ANIMATE,
        params,
        -1,
      ),
    )
  }

  async getCompletedJobs(): Promise<ThreeDGenJobEvent[]> {
    return this.rpcClient.call<ThreeDGenJobEvent[]>(
      RundotGameMessageId.H5_POLL_COMPLETED_JOBS,
      { type: 'threeDGen' },
    )
  }
}
