import type { Host } from '../Host';
import type { RundotGameAPI } from '../rundot-game-api/types';

export * from './AudioGenApi';
export { RpcAudioGenApi } from './RpcAudioGenApi';
export { MockAudioGenApi } from './MockAudioGenApi';
// HttpAudioGenApi is intentionally NOT exported here.
// It depends on Firebase and should only be imported by PlaygroundHost.
// This prevents Firebase from being bundled in production builds.

export function initializeAudioGen(rundotGameApi: RundotGameAPI, host: Host): void {
  rundotGameApi.audioGen = host.audioGen;
}
