export class RemoteHost implements Host {
  readonly ads: AdsApi
  readonly analytics: AnalyticsApi
  readonly deviceCache: StorageApi
  readonly appStorage: StorageApi
  readonly ownerStorage: StorageApi
  readonly sharedStorage: SharedStorageHostApi
  readonly avatar3d: Avatar3dApi
  readonly navigation: NavigationApi
  readonly notifications: NotificationsApi
  readonly popups: PopupsApi
  readonly profile: ProfileApi
  readonly system: SystemApi
  readonly cdn: CdnApi
  readonly time: TimeApi
  ai: AiApi
  textGen: TextGenApi
  readonly haptics: HapticsApi
  readonly gamepad: GamepadApi
  readonly features: FeaturesApi
  readonly liveops: LiveOpsApi
  readonly lifecycle: LifecycleApi
  simulation: SimulationApi
  rooms: RoomsApi
  readonly logging: LoggingApi
  readonly iap: IapApi
  readonly credits: CreditsApi
  readonly leaderboard: LeaderboardApi
  ugc: UgcApi
  readonly preloader: PreloaderApi
  readonly social: SocialApi
  imageGen: ImageGenApi
  audioGen: AudioGenApi
  videoGen: VideoGenApi
  files: FilesApi
  clips: ClipsApi
  spriteGen: SpriteGenApi
  threeDGen: ThreeDGenApi
  readonly entitlements: EntitlementApi
  readonly choices: ChoicesApi
  readonly stats: StatsApi
  readonly collectibles: CollectiblesApi
  readonly shop: ShopApi
  readonly accessGate: AccessGateApi
  readonly multiplayer: MultiplayerApi
  readonly video: VideoApi
  readonly activity: ActivityApi
  readonly app: AppApi
  readonly attribution: AttributionApi

  context?: InitializationContext
  instanceId: string = 'unknown'

  get isInitialized() {
    return this._isInitialized
  }

  private readonly rundotGameApi: RundotGameAPI
  private readonly rpcClient: RpcClient
  private _isInitialized: boolean = false
  private _roomServerUrl: string = ''

  constructor(rundotGameApi: RundotGameAPI) {
    this.rundotGameApi = rundotGameApi
    const rpcClient = new RpcClient()
    this.rpcClient = rpcClient

    this.ads = new RpcAdsApi(rpcClient)
    this.analytics = new RpcAnalyticsApi(rpcClient)
    this.deviceCache = new RpcStorageApi(rpcClient, {
      clear: RundotGameMessageId.DEVICE_CACHE_CLEAR,
      getItem: RundotGameMessageId.DEVICE_CACHE_GET_ITEM,
      getKey: RundotGameMessageId.DEVICE_CACHE_KEY,
      length: RundotGameMessageId.DEVICE_CACHE_LENGTH,
      removeItem: RundotGameMessageId.DEVICE_CACHE_REMOVE_ITEM,
      setItem: RundotGameMessageId.DEVICE_CACHE_SET_ITEM,
    })
    this.appStorage = new ValidatingStorageApi(
      new RpcStorageApi(rpcClient, {
        clear: RundotGameMessageId.APP_STORAGE_CLEAR,
        getItem: RundotGameMessageId.APP_STORAGE_GET_ITEM,
        getKey: RundotGameMessageId.APP_STORAGE_KEY,
        length: RundotGameMessageId.APP_STORAGE_LENGTH,
        removeItem: RundotGameMessageId.APP_STORAGE_REMOVE_ITEM,
        setItem: RundotGameMessageId.APP_STORAGE_SET_ITEM,
        getAllItems: RundotGameMessageId.APP_STORAGE_GET_ALL_ITEMS,
        getAllData: RundotGameMessageId.APP_STORAGE_GET_ALL_DATA,
        setMultipleItems: RundotGameMessageId.APP_STORAGE_SET_MULTIPLE_ITEMS,
        removeMultipleItems: RundotGameMessageId.APP_STORAGE_REMOVE_MULTIPLE_ITEMS,
      }),
    )
    this.ownerStorage = new ValidatingStorageApi(
      new RpcStorageApi(rpcClient, {
        clear: RundotGameMessageId.OWNER_STORAGE_CLEAR,
        getItem: RundotGameMessageId.OWNER_STORAGE_GET_ITEM,
        getKey: RundotGameMessageId.OWNER_STORAGE_KEY,
        length: RundotGameMessageId.OWNER_STORAGE_LENGTH,
        removeItem: RundotGameMessageId.OWNER_STORAGE_REMOVE_ITEM,
        setItem: RundotGameMessageId.OWNER_STORAGE_SET_ITEM,
        getAllItems: RundotGameMessageId.OWNER_STORAGE_GET_ALL_ITEMS,
        getAllData: RundotGameMessageId.OWNER_STORAGE_GET_ALL_DATA,
        setMultipleItems: RundotGameMessageId.OWNER_STORAGE_SET_MULTIPLE_ITEMS,
        removeMultipleItems: RundotGameMessageId.OWNER_STORAGE_REMOVE_MULTIPLE_ITEMS,
      }),
    )

    // Shared storage (M3). `open` and `read` return synchronous handles; the
    // first method call on each handle performs the server-side policy check.
    // Handles are lightweight and not cached — multiple opens on the same
    // (targetAppId, namespace) pair produce independent Rpc-bound instances.
    this.sharedStorage = {
      open: ({ appId, namespace }: { appId?: string; namespace: string }) => {
        if (appId === '') {
          throw new Error(
            'sharedStorage.open: appId must be a non-empty string or omitted',
          )
        }
        return new ValidatingStorageApi(
          new DualEmitStorageApi(
            rpcClient,
            {
              clear: RundotGameMessageId.SHARED_STORAGE_CLEAR,
              getItem: RundotGameMessageId.SHARED_STORAGE_GET_ITEM,
              getKey: RundotGameMessageId.SHARED_STORAGE_KEY,
              length: RundotGameMessageId.SHARED_STORAGE_LENGTH,
              removeItem: RundotGameMessageId.SHARED_STORAGE_REMOVE_ITEM,
              setItem: RundotGameMessageId.SHARED_STORAGE_SET_ITEM,
              getAllItems: RundotGameMessageId.SHARED_STORAGE_GET_ALL_ITEMS,
              getAllData: RundotGameMessageId.SHARED_STORAGE_GET_ALL_DATA,
              setMultipleItems: RundotGameMessageId.SHARED_STORAGE_SET_MULTIPLE_ITEMS,
              removeMultipleItems: RundotGameMessageId.SHARED_STORAGE_REMOVE_MULTIPLE_ITEMS,
            },
            { targetAppId: appId, namespace },
            {
              clear: RundotGameMessageId.GLOBAL_STORAGE_CLEAR,
              getItem: RundotGameMessageId.GLOBAL_STORAGE_GET_ITEM,
              getKey: RundotGameMessageId.GLOBAL_STORAGE_KEY,
              length: RundotGameMessageId.GLOBAL_STORAGE_LENGTH,
              removeItem: RundotGameMessageId.GLOBAL_STORAGE_REMOVE_ITEM,
              setItem: RundotGameMessageId.GLOBAL_STORAGE_SET_ITEM,
              getAllItems: RundotGameMessageId.GLOBAL_STORAGE_GET_ALL_ITEMS,
              setMultipleItems: RundotGameMessageId.GLOBAL_STORAGE_SET_MULTIPLE_ITEMS,
              removeMultipleItems: RundotGameMessageId.GLOBAL_STORAGE_REMOVE_MULTIPLE_ITEMS,
            },
          ),
        )
      },
      read: ({ appId, namespace }: { appId?: string; namespace: string }) => {
        if (appId === '') {
          throw new Error(
            'sharedStorage.read: appId must be a non-empty string or omitted',
          )
        }
        return new RpcInboundStorageApi(
          rpcClient,
          {
            listSources: RundotGameMessageId.SHARED_STORAGE_INBOUND_LIST_SOURCES,
            get: RundotGameMessageId.SHARED_STORAGE_INBOUND_GET,
            getAllFromSource:
              RundotGameMessageId.SHARED_STORAGE_INBOUND_GET_ALL_FROM_SOURCE,
            getAllForKey:
              RundotGameMessageId.SHARED_STORAGE_INBOUND_GET_ALL_FOR_KEY,
          },
          { targetAppId: appId, namespace },
        )
      },
    }

    this.avatar3d = new RpcAvatarApi(rpcClient, rundotGameApi)
    this.navigation = new RpcNavigationApi(rpcClient, rundotGameApi)
    this.notifications = new RpcNotificationsApi(rpcClient, {
      recordDeprecationEvent: (eventName) => {
        void this.analytics.recordCustomEvent(eventName, {})
      },
    })
    this.popups = new RpcPopupsApi(rpcClient)
    this.profile = new HostProfileApi(rundotGameApi)

    // Create device and environment APIs and combine into system namespace
    const deviceApi = new HostDeviceApi(rundotGameApi)
    const environmentApi = new HostEnvironmentApi(rundotGameApi)
    this.system = new HostSystemApi(deviceApi, environmentApi, rundotGameApi, rpcClient)

    this.cdn = new HostCdnApi(rpcClient)
    this.time = new HostTimeApi(rpcClient, rundotGameApi)
    this.ai = new RpcAiApi(rpcClient)
    this.textGen = this.ai
    this.haptics = new RpcHapticsApi(rpcClient)
    // The handshake must fire only after the transport is live, so defer the
    // subscribe to initialize() (after rpcClient.start + READY).
    this.gamepad = new RpcGamepadApi(rpcClient, { autoSubscribe: false })
    this.features = new RpcFeaturesApi(rpcClient)
    this.liveops = new RpcLiveOpsApi(rpcClient, {
      getUnitId: () => this.rundotGameApi._profileData?.id,
      onExposure: (assignment, configVersion) => {
        // Fire-and-forget: recordCustomEvent is async, so a rejection would escape
        // the deduper's synchronous try/catch as an unhandledRejection. Swallow it —
        // exposure logging must never surface as a game-visible error.
        void this.analytics
          .recordCustomEvent('liveops_experiment_exposure', {
            experiment_id: assignment.experimentId,
            variant_id: assignment.variantId,
            variant_weight: assignment.variantWeight,
            total_weight: assignment.totalWeight,
            config_version: configVersion,
          })
          .catch(() => {})
      },
    })
    this.lifecycle = new RpcLifecycleApi(rpcClient)
    this.simulation = new RpcSimulationApi(rpcClient)
    this.rooms = new RpcRoomsApi(rpcClient)
    this.logging = new RpcLoggingApi(this, rpcClient)
    this.iap = new RpcIapApi(rpcClient)
    this.credits = new RpcCreditsApi(rpcClient)
    this.leaderboard = new RpcLeaderboardApi(rpcClient)
    this.ugc = new RpcUgcApi(rpcClient)
    this.preloader = new RpcPreloaderApi(rpcClient)
    this.social = new RpcSocialApi(rpcClient)
    this.imageGen = new RpcImageGenApi(rpcClient)
    this.audioGen = new RpcAudioGenApi(rpcClient)
    this.videoGen = new RpcVideoGenApi(rpcClient)
    this.files = new RpcFilesApi(rpcClient)
    this.clips = new ClipsApiImpl({
      files: this.files,
      ugc: this.ugc,
      captureConsent: new RpcCaptureConsent(rpcClient),
    })
    this.spriteGen = new RpcSpriteGenApi(rpcClient)
    this.threeDGen = new RpcThreeDGenApi(rpcClient)
    this.entitlements = new RpcEntitlementApi(rpcClient)
    this.choices = new RpcChoicesApi(rpcClient)
    this.stats = new RpcStatsApi(rpcClient)
    this.collectibles = new RpcCollectiblesApi(rpcClient)
    this.shop = new RpcShopApi(rpcClient)
    this.video = new RpcVideoApi(rpcClient)
    this.activity = new RpcActivityApi(rpcClient)
    this.app = new RpcAppApi(rpcClient)
    this.attribution = new RpcAttributionApi(rpcClient)
    rundotGameApi.isMock = () => false
    this.rundotGameApi.sharedAssets = new RpcSharedAssetsApi(rpcClient, rundotGameApi)

    initializeRoomsApi(this.rundotGameApi, this)

    this.accessGate = new RpcAccessGateApi(rpcClient, rundotGameApi)

    // Multiplayer API — gets join ticket via RPC to native host
    // serverUrl and gameId are resolved lazily after initialize() populates them from InitResponse
    this.multiplayer = new WsMultiplayerApi({
      serverUrl: () => this._roomServerUrl,
      getJoinTicket: async (req) => {
        const result = await rpcClient.call<{ ticket: string }>(
          RundotGameMessageId.H5_REQUEST_JOIN_TICKET,
          req,
        )
        return result.ticket
      },
      listUserRooms: async (options) => {
        const result = await rpcClient.call<{ rooms: RealtimeRoomSummary[] }>(
          RundotGameMessageId.H5_LIST_USER_REALTIME_ROOMS,
          options ?? {},
        )
        return result.rooms
      },
    })

    applyAccessGates(this)
  }

  async initialize(
    options?: InitializationOptions,
  ): Promise<InitializationContext> {
    const transport = new RundotGameTransport()
    transport.start()
    this.rpcClient.start(transport)

    // Keep _profileData in sync the instant identity changes, BEFORE any game
    // onIdentityChanged callback runs (registration order). Registered here so
    // it precedes every game-side subscription, which can only happen post-init.
    wireIdentityReplica(this.rpcClient, this.rundotGameApi)

    // Set up room notification routing in RpcRoomsApi
    const roomsApi = this.rooms as RpcRoomsApi
    roomsApi.setupNotifications(transport)

    const response = await this.rpcClient.call<InitResponse>(
      RundotGameMessageId.INIT_SDK,
      buildInitSdkArgs(),
      -1,
    )

    transport.instanceId = response.instanceId
    this.instanceId = response.instanceId
    this._roomServerUrl = response.roomServerUrl ?? ''
    // Store data on RundotGameAPI instance (not global window.rundotGameApi)
    // Profile, device, and environment are all required in InitResponse
    this.rundotGameApi._profileData = sanitizeProfile(response.profile)
    this.rundotGameApi._deviceData = response.device
    this.rundotGameApi._environmentData = response.environment
    this.rundotGameApi._localeData = response.locale
    this.rundotGameApi._languageCodeData = response.languageCode

    this._isInitialized = true

    await this.rpcClient.call(RundotGameMessageId.READY, {})

    // Fire the gamepad handshake now that the transport is live. Fire-and-forget:
    // gamepad capability resolves asynchronously via isSupported().
    void (this.gamepad as RpcGamepadApi).subscribe()

    const safeArea = response.safeArea
    if (safeArea) {
      // Store internally for system.getSafeArea()
      this.rundotGameApi._safeAreaData = safeArea
    }

    // Extract G2G navigation context and strip it from launchParams so
    // launchParams stays a clean Record<string, string> for consumers.
    const { g2gLaunch, g2gReturn, ...launchParams } = response.launchParams ?? {}

    this.context = buildInitializationContext(
      {
        safeArea,
        initializeAsleep: response.initializeAsleep,
        launchParams,
        shareParams: response.shareParams,
        notificationParams: response.notificationParams,
        shareLinkId: response.shareLinkId,
        g2gLaunch,
        g2gReturn,
      },
      (field) => {
        // Data-driven deprecation: surface reads to Datadog so removal (v6.0.0)
        // can be gated on real adoption telemetry. Fire-and-forget.
        void this.analytics.recordCustomEvent('sdk_deprecated_context_read', {
          field,
        })
      },
    )

    return this.context
  }

  onNotificationParamsUpdate(
    callback: (params: Record<string, string>) => void,
  ): () => void {
    const subscription = this.rpcClient.onNotification<Record<string, string>>(
      RundotGameMessageId.NOTIFICATION_PARAMS_UPDATE,
      callback,
    )
    return () => subscription.unsubscribe()
  }

  notifyNotificationParamsSubscribeReady(): void {
    this.rpcClient.notify(
      RundotGameMessageId.NOTIFICATION_PARAMS_SUBSCRIBE_READY,
    )
  }
}

/** Snapshot of the INIT_SDK intent fields used to build the launch context. */
export interface InitializationContextSnapshot {
  safeArea?: SafeArea
  initializeAsleep: boolean
  launchParams?: Record<string, string>
  shareParams?: Record<string, string>
  notificationParams?: Record<string, string>
  shareLinkId?: string
  g2gLaunch?: Record<string, unknown>
  g2gReturn?: Record<string, unknown>
}

/** Invoked once per intent field per session, the first time it is read. */
export type DeprecatedContextReadHook = (field: string) => void

/**
 * Build the `InitializationContext` from the INIT_SDK snapshot. The four launch
 * intent fields (`launchParams`, `shareParams`, `notificationParams`,
 * `shareLinkId`) are defined as deprecation-warning getters over the snapshot
 * values: on first read per field per session they `console.warn` once and
 * invoke `onDeprecatedRead`. They still return the real INIT value, so behavior
 * is unchanged. These getters are the legacy snapshot read path — they are NOT
 * backed by the launch-signal latch and may differ from `resolveLaunchIntent`
 * for a deferred link (that is the entire reason the new API exists).
 */
export function buildInitializationContext(
  snapshot: InitializationContextSnapshot,
  onDeprecatedRead?: DeprecatedContextReadHook,
): InitializationContext {
  const context = {
    safeArea: snapshot.safeArea,
    initializeAsleep: snapshot.initializeAsleep,
    g2gLaunch: snapshot.g2gLaunch as Record<string, any> | undefined,
    g2gReturn: snapshot.g2gReturn as Record<string, any> | undefined,
  } as InitializationContext

  const warned = new Set<string>()
  const defineDeprecatedIntentField = <T>(field: string, value: T): void => {
    Object.defineProperty(context, field, {
      enumerable: true,
      configurable: true,
      get(): T {
        if (!warned.has(field)) {
          warned.add(field)
          console.warn(
            `RundotGameAPI.context.${field} is deprecated; use RundotGameAPI.app.resolveLaunchIntent(). Removed in v6.0.0.`,
          )
          onDeprecatedRead?.(field)
        }
        return value
      },
    })
  }

  defineDeprecatedIntentField('launchParams', snapshot.launchParams)
  defineDeprecatedIntentField('shareParams', snapshot.shareParams)
  defineDeprecatedIntentField('notificationParams', snapshot.notificationParams)
  defineDeprecatedIntentField('shareLinkId', snapshot.shareLinkId)

  return context
}

export interface InitResponse {
  initializeAsleep: boolean
  instanceId: string
  /** Game ID — used by multiplayer API to connect to the correct room server */
  gameId?: string
  /** Room server URL for multiplayer WebSocket connections */
  roomServerUrl?: string
  profile: {
    id: string
    username: string
    avatarUrl?: string | null
    isAnonymous?: boolean
  }
  safeArea?: SafeArea
  launchParams: Record<string, string> & {
    /** Present when this game was launched via game-to-game navigation. The games (source and destination) define the contract. */
    g2gLaunch?: Record<string, any>
    g2gReturn?: Record<string, any>
  }
  shareParams: Record<string, string>
  notificationParams?: Record<string, string>
  shareLinkId?: string
  environment: RawEnvironmentInfo
  device: DeviceInfo
  locale: string
  languageCode: string
  rooms?: {
    gameType?: string
    rulesPreset?: string
    matchmaking?: Record<string, any>
    createOptions?: Record<string, any>
    privateMatchDefaults?: Record<string, any>
    [key: string]: any
  }
}
