import { VideoGenApi, VideoGenParams, VideoGenResult, VideoGenJobEvent, VideoGenJobStartedEvent } from './VideoGenApi'
import { RpcClient, Subscription } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import { mapCreditsExhaustion } from '../credits/CreditsApi'

export class RpcVideoGenApi implements VideoGenApi {
  constructor(private readonly rpcClient: RpcClient) {}

  async generate(params: VideoGenParams): Promise<VideoGenResult> {
    // Surface player creator-credit exhaustion as a typed CreditsExhaustedError.
    return mapCreditsExhaustion(
      this.rpcClient.call<VideoGenResult>(
        RundotGameMessageId.H5_VIDEO_GEN_GENERATE,
        params,
        -1,
      ),
    )
  }

  async getCompletedJobs(): Promise<VideoGenJobEvent[]> {
    return this.rpcClient.call<VideoGenJobEvent[]>(
      RundotGameMessageId.H5_POLL_COMPLETED_JOBS,
      { type: 'videoGen' },
    )
  }

  async cancel(jobId: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_VIDEO_GEN_CANCEL,
      { jobId },
    )
  }

  onJobStarted(callback: (event: VideoGenJobStartedEvent) => void): Subscription {
    return this.rpcClient.onNotification<VideoGenJobStartedEvent>(
      RundotGameMessageId.H5_VIDEO_GEN_JOB_STARTED,
      callback,
    )
  }
}
