/**
 * Safe area insets representing padding needed to avoid device notches and host UI.
 * Includes toolbar/feedHeader height + device safe areas.
 */
export interface SafeArea {
  left: number
  top: number
  right: number
  bottom: number
}

/**
 * @deprecated Use SafeArea instead. Will be removed in v4.0.0
 */
export type HudInsets = SafeArea

export interface InitializationOptions {
  helpText?: string
  hardDisableMock?: boolean
  mock?: Record<string, any>
  usePreloader?: boolean
  launchParams?: Record<string, string>
  shareParams?: Record<string, string>
  notificationParams?: Record<string, string>
}

export interface InitializationContext {
  /**
   * Safe area insets from INIT_SDK response.
   * @deprecated Use RundotGameAPI.system.getSafeArea() instead. Will be removed in v4.0.0
   */
  safeArea?: SafeArea
  initializeAsleep: boolean
  /**
   * @deprecated Use RundotGameAPI.app.resolveLaunchIntent() instead. This is
   * the legacy INIT-snapshot read path and cannot represent a deferred deep
   * link. Will be removed in v6.0.0.
   */
  launchParams?: Record<string, string>
  /**
   * @deprecated Use RundotGameAPI.app.resolveLaunchIntent() instead. This is
   * the legacy INIT-snapshot read path and cannot represent a deferred share
   * link. Will be removed in v6.0.0.
   */
  shareParams?: Record<string, string>
  /**
   * @deprecated Use RundotGameAPI.app.resolveLaunchIntent() instead. Will be
   * removed in v6.0.0.
   */
  notificationParams?: Record<string, string>
  /**
   * The share document ID when launched from a share link; `undefined` otherwise.
   * @deprecated Use RundotGameAPI.app.resolveLaunchIntent() instead. Will be
   * removed in v6.0.0.
   */
  shareLinkId?: string
  /** Data passed from a source game via game-to-game navigation (forward). */
  g2gLaunch?: Record<string, any>
  /** Data restored from a source game via game-to-game return navigation. */
  g2gReturn?: Record<string, any>
}

