import {
  ChoicesApi,
  ChoicesBalance,
  ChoicesSpendRequest,
  ChoicesSpendResult,
} from './ChoicesApi'
import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'

/**
 * RN-bridge implementation of `ChoicesApi`. The RN host receives the
 * message, calls the corresponding venus endpoint with the Firebase
 * token + GST it already holds, and returns the result. Games (run-tv)
 * consume this transparently via `RundotGameAPI.choices.*`.
 */
export class RpcChoicesApi implements ChoicesApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async getBalance(): Promise<ChoicesBalance> {
    return this.rpcClient.call<ChoicesBalance>(
      RundotGameMessageId.H5_CHOICES_GET_BALANCE,
      {},
    )
  }

  async spend(request: ChoicesSpendRequest): Promise<ChoicesSpendResult> {
    return this.rpcClient.call<ChoicesSpendResult>(
      RundotGameMessageId.H5_CHOICES_SPEND,
      { ...request },
    )
  }
}
