import { RpcClient } from '../rpc'
import { RundotGameMessageId } from '../RundotGameMessageId'
import type {
  AdminUgcApi,
  AdminUgcBrowseParams,
  AdminUgcBrowseResponse,
  AdminUgcListReportsParams,
  AdminUgcListReportsResponse,
  AdminUgcResolveAction,
} from './AppApi'

export class RpcAdminUgcApi implements AdminUgcApi {
  private readonly rpcClient: RpcClient

  constructor(rpcClient: RpcClient) {
    this.rpcClient = rpcClient
  }

  async browse(
    params?: AdminUgcBrowseParams,
  ): Promise<AdminUgcBrowseResponse> {
    return this.rpcClient.call<AdminUgcBrowseResponse>(
      RundotGameMessageId.H5_APP_ADMIN_UGC_BROWSE,
      params ?? {},
    )
  }

  async removeEntry(entryId: string): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_APP_ADMIN_UGC_REMOVE_ENTRY,
      { entryId },
    )
  }

  async listReports(
    params?: AdminUgcListReportsParams,
  ): Promise<AdminUgcListReportsResponse> {
    return this.rpcClient.call<AdminUgcListReportsResponse>(
      RundotGameMessageId.H5_APP_ADMIN_UGC_LIST_REPORTS,
      params ?? {},
    )
  }

  async resolveReport(
    reportId: string,
    action: AdminUgcResolveAction,
  ): Promise<void> {
    await this.rpcClient.call<void>(
      RundotGameMessageId.H5_APP_ADMIN_UGC_RESOLVE_REPORT,
      { reportId, action },
    )
  }
}
