import type { Host } from '../Host'
import type { RundotGameAPI } from '../rundot-game-api/types'

export * from './ThreeDGenApi'
export { RpcThreeDGenApi } from './RpcThreeDGenApi'
export { MockThreeDGenApi } from './MockThreeDGenApi'
// HttpThreeDGenApi is intentionally NOT exported here.
// It depends on Firebase and should only be imported by PlaygroundHost.
// This prevents Firebase from being bundled in production builds.

export function initializeThreeDGen(rundotGameApi: RundotGameAPI, host: Host): void {
  rundotGameApi.threeDGen = host.threeDGen
}
