import type { Host } from '../Host';
import type { RundotGameAPI } from '../rundot-game-api/types';

export * from './ImageGenApi';
export { RpcImageGenApi } from './RpcImageGenApi';
export { MockImageGenApi } from './MockImageGenApi';
// HttpImageGenApi is intentionally NOT exported here.
// It depends on Firebase and should only be imported by PlaygroundHost.
// This prevents Firebase from being bundled in production builds.

export function initializeImageGen(rundotGameApi: RundotGameAPI, host: Host): void {
  rundotGameApi.imageGen = host.imageGen;
}
